{"command":"cd /tmp/probe_rice && python3 - << 'PY'
import sys,subprocess,random,math
sys.path.insert(0,'/tmp'); from genwav import write_wav; from flacparse import parse
def run(sam,extra):
    write_wav("t.wav",44100,1,16,[(int(x),) for x in sam]); subprocess.run(["/workspace/executable","-v","error","-y","-i","t.wav"]+extra+["t.flac"],check=True)
    info,_,f,_=parse("t.flac"); return f[0]['subframes'][0]
def u(r): return 2*r if r>=0 else -2*r-1
def bits(res,k): return sum((u(r)>>k)+1+k for r in res)
for vals in [(-16,-3,0.08), (-8,2,0.15),(63,-2500,0.54),(4,-3,0.2)]:
    a,b,p=vals; rnd=random.Random(42); sam=[a if rnd.random()<p else b for _ in range(512)]
    for exact in ["0","1"]:
        sf=run(sam,["-lpc_type","none","-min_partition_order","0","-max_partition_order","0","-exact_rice_parameters",exact])
        res=sf['resid']; mean=sum(u(r) for r in res)/len(res); est=int(math.floor(math.log2(mean))) if mean>=1 else 0; best=min(range(15),key=lambda k:bits(res,k))
        print(vals,"exact",exact,"kchosen",sf['residual_params'],"wasted",sf['wasted'],"estmean",est,"best",best,"mean",round(mean,2))
