def predict(sam):
    L=sum(abs(x) for x,y in sam); R=sum(abs(y) for x,y in sam); S=sum(abs(x-y) for x,y in sam); M=sum(abs((x+y)>>1) for x,y in sam)
    costs={1:L+R,8:L+S,9:S+R,10:M+S}
    # ties preserving order list [indep,left,right,mid] with < only
    best=1; bestv=costs[1]
    for mode in [8,9,10]:
        if costs[mode]<bestv: best=mode; bestv=costs[mode]
    return best,costs

