        elif mode==1: x=rnd.randint(-15000,15000); y=x+rnd.randint(-3000,3000)
        elif mode==2: x=int(10000*math.sin(i*0.1)); y=int(9000*math.sin(i*0.1+0.5))
        else: x=rnd.randint(-2000,2000); y=rnd.randint(-20000,20000)
        sam.append((x,max(-32767,min(32767,y))))
