    info,_,frames,_=parse("t.flac")
    # block is one frame (2205<4608)
    actual=frames[0]['chassign']; pred,costs=predict(sam); total+=1
    if pred!=actual: mismatch+=1; print(seed,mode,"actual",actual,"pred",pred,costs)
print("mismatch",mismatch,"/",total)
