def metrics(sam):
    A=sum(abs(x) for x,y in sam); B=sum(abs(y) for x,y in sam); C=sum(abs(x-y) for x,y in sam); M=sum(abs((x+y)>>1) for x,y in sam)
    A2=sum(x*x for x,y in sam); B2=sum(y*y for x,y in sam); C2=sum((x-y)**2 for x,y in sam); M2=sum(((x+y)>>1)**2 for x,y in sam); D2=sum((x+y)**2 for x,y in sam)
    return dict(A=A,B=B,C=C,M=M,A2=A2,B2=B2,C2=C2,M2=M2,D2=D2)
def argmin(cost, order=[1,8,9,10]):
    best=order[0]
    for m in order[1:]:
        if cost[m]<cost[best]: best=m
    return best
def models(s):
    return {
      'L1':{1:s['A']+s['B'],8:s['A']+s['C'],9:s['B']+s['C'],10:s['M']+s['C']},
      'L2':{1:s['A2']+s['B2'],8:s['A2']+s['C2'],9:s['B2']+s['C2'],10:s['M2']+s['C2']},
      'L2_D2':{1:s['A2']+s['B2'],8:s['A2']+s['C2'],9:s['B2']+s['C2'],10:s['D2']+s['C2']},
      'sqrtL2':{1:math.sqrt(s['A2'])+math.sqrt(s['B2']),8:math.sqrt(s['A2'])+math.sqrt(s['C2']),9:math.sqrt(s['B2'])+math.sqrt(s['C2']),10:math.sqrt(s['M2'])+math.sqrt(s['C2'])},
    }
data=[]
for seed in range(20):
    for mode in range(6):
        rnd=random.Random(seed*31+mode); sam=[]
        for i in range(2205):
            if mode==0: x=rnd.randint(-15000,15000); y=rnd.randint(-15000,15000)
            elif mode==1: x=rnd.randint(-15000,15000); y=x+rnd.randint(-3000,3000)
            elif mode==2: x=int(10000*math.sin(i*0.1)); y=int(9000*math.sin(i*0.1+0.5))
            elif mode==3: x=rnd.randint(-2000,2000); y=rnd.randint(-20000,20000)
            elif mode==4: x=rnd.randint(-15000,15000); y=-x+rnd.randint(-3000,3000)
