import sys,subprocess,random,math,json,collections
sys.path.insert(0,'/tmp'); from genwav import write_wav
# LPC channel bits estimate
def windowed(seq):
    N=len(seq); s=[]
    for i,x in enumerate(seq):
        if N%2==1 and i==N//2: s.append(0.0)
        else:
            d=min(i+1,N-i); s.append(x*(d*d-1-4*d/N))
    return s
def lpc_analysis(seq):
    # returns order, coeffs (quantized), shift, residual list (after warm), refs
    # wasted bits handling
    # compute wasted: OR all samples
    orv=0
    for x in seq: orv|=x
    # count trailing zeros of orv in 2's complement? For negative numbers Python infinite bits - use & 0xffffffff? FFmpeg wasted for int32 samples: They iterate samples and count trailing zeros of each sample? Need approximate: if all zero wasted0 else min ctz of abs? We'll compute using x & -x lowbit for x !=0.
    if all(x==seq[0] for x in seq):
        return {'type':'const','bits_est': 1+ (16), 'resid_sum':0}
    wasted=None
    for x in seq:
        if x==0: continue
        tz=(x & -x).bit_length()-1  # for negative Python: -x positive, x&-x lowbit works? for x=-8, x&-x=8
        wasted=tz if wasted is None else min(wasted,tz)
    if wasted is None: wasted=0
    sh=[x>>wasted for x in seq]
    # order estimation max8
    maxo=8; s=windowed(sh); N=len(sh)
    autoc=[sum(s[i]*s[i+k] for i in range(N-k)) for k in range(maxo+1)]
    if autoc[0]==0: return {'type':'zero','bits_est':0,'resid_sum':0}
    a=[0.0]*maxo; e=autoc[0]; refs=[]; coeffs_by_order={}
    for i in range(maxo):
        acc=autoc[i+1]-sum(a[j]*autoc[i-j] for j in range(i)); alpha=acc/e; refs.append(alpha); an=a[:]; an[i]=alpha
        for j in range(i): an[j]=a[j]-alpha*a[i-1-j]
        a=an; e*=1-alpha*alpha; coeffs_by_order[i+1]=a[:i+1]
        if e<=0: break
    order=1
    for i,r in enumerate(refs,1):
        if abs(r)>0.1: order=i
    co=coeffs_by_order[order]
    maxa=max(abs(x) for x in co); shift=int(math.floor(math.log2(16383/maxa))) if maxa>0 else 15; shift=max(-16,min(15,shift)); q=[round(x*(1<<shift)) for x in co]
    resid=[]
    for i in range(order,len(sh)):
        pred=sum(q[j]*sh[i-j-1] for j in range(order))>>shift; resid.append(sh[i]-pred)
    return {'type':'lpc','order':order,'q':q,'shift':shift,'resid':resid,'wasted':wasted,'blocksize':len(seq)}
def uval(r): return 2*r if r>=0 else -2*r-1
