        if order_method=='fwd': total=sum(terms)
        elif order_method=='rev': total=sum(reversed(terms))
        elif order_method=='pair2':
            a=b=0.0
            for idx,t in enumerate(terms):
                if idx%2==0: a+=t
                else: b+=t
            total=a+b
        elif order_method=='pair4':
            acc=[0.0]*4
            for idx,t in enumerate(terms): acc[idx%4]+=t
            total=((acc[0]+acc[1])+(acc[2]+acc[3]))
        elif order_method=='pair4_seq':
            acc=[0.0]*4
            for idx,t in enumerate(terms): acc[idx%4]+=t
            total=0.0
            for v in acc: total+=v
        elif order_method=='chunk128':
            total=0.0
            for st in range(0,len(terms),128): total+=sum(terms[st:st+128])
        autoc.append(total)
    a=[0.]*maxo; e=autoc[0]; refs=[]; outs={}
