    for i,r in enumerate(refs,1):
        if abs(r)>0.1: order=i
    co=outs[order]; mx=max(abs(x) for x in co); shift=int(math.floor(math.log2(16383/mx))); q=[round(x*(1<<shift)) for x in co]
    return order,shift,q,co

def gen(kind):
    if kind=='sine': return [int(round(4096*math.sin(2*math.pi*440*i/44100))) for i in range(4608)]
