        for amp in [4095,4096]:
            for inter in ['nearest_floor','nearest_round','linear','linear_inttab']:
                err=exact=0
                # integer table for linear_inttab
                itab=[round(amp*x) for x in tab]
                for i,x in enumerate(s):
                    ph=(i*freq/sr)*N
                    if inter=='nearest_floor': pred=round(amp*tab[int(ph)%N])
                    elif inter=='nearest_round': pred=round(amp*tab[round(ph)%N])
                    elif inter=='linear':
                        j=int(ph)%N; frac=ph-math.floor(ph); pred=round(amp*((1-frac)*tab[j]+frac*tab[(j+1)%N]))
                    else:
                        j=int(ph)%N; frac=ph-math.floor(ph); pred=round((1-frac)*itab[j]+frac*itab[(j+1)%N])
                    err+=abs(x-pred); exact+=x==pred
                results.append((err,-exact,logN,amp,inter))
    results.sort(); print(freq,results[:5])
