        self.data=data; self.info=None; self.metadata=[]; self.vendor=b''; self.comments=[]; self.frames_start=None; self.other_metadata_blocks=[]
        self._parse_header()
    def _parse_header(self):
        data=self.data
        if len(data)<4 or data[:4]!=b'fLaC':
            raise ValueError('not a FLAC stream')
        off=4
        while off+4 <= len(data):
            hdr=data[off]; last=hdr>>7; typ=hdr&0x7f; length=int.from_bytes(data[off+1:off+4],'big'); block=data[off+4:off+4+length]
            if typ==0 and length>=34:
                self.info=FlacStreamInfo.from_bytes(block[:34])
            elif typ==4:
                try:
                    vl=int.from_bytes(block[0:4],'little'); self.vendor=block[4:4+vl]; cnt=int.from_bytes(block[4+vl:8+vl],'little'); p=8+vl
                    for _ in range(cnt):
                        l=int.from_bytes(block[p:p+4],'little'); txt=block[p+4:p+4+l].decode('utf-8','replace'); p+=4+l
                        if '=' in txt:
                            k,v=txt.split('=',1); self.comments.append((k.lower(),v)); self.metadata.append((k.lower(),v))
                        else:
                            self.comments.append((txt,'')); 
                except Exception:
                    pass
            else:
                self.other_metadata_blocks.append((typ,bytes(block)))
            off += 4+length
            if last: break
        self.frames_start=off
    def _read_residual(self, br, blocksize, order):
        method=br.read(2)
        if method>1: raise ValueError('invalid residual coding method')
        porder=br.read(4); nparts=1<<porder; pbits=4 if method==0 else 5; escape=(1<<pbits)-1
        part_counts=[]
        if nparts==1:
            part_counts=[blocksize-order]
        else:
            if blocksize % nparts !=0: raise ValueError('invalid partition')
            p=blocksize//nparts; part_counts=[p-order]+[p]*(nparts-1)
        resid=[]
        for cnt in part_counts:
            if cnt <0: raise ValueError('invalid partition count')
            param=br.read(pbits)
            if param==escape:
                rawbits=br.read(5)
                for _ in range(cnt):
                    resid.append(br.read_signed(rawbits) if rawbits else 0)
            else:
                for _ in range(cnt):
                    q=br.read_unary()
                    u=(q<<param) | (br.read(param) if param else 0)
                    resid.append((u>>1) ^ -(u&1))
        return resid
    def _decode_subframe(self, br, blocksize, bps):
        pad=br.read(1)
        typ=br.read(6); wasted_flag=br.read(1); wasted=0
        if wasted_flag:
            wasted=1
            while br.read(1)==0: wasted+=1
        eff=bps-wasted
        if eff<=0: raise ValueError('invalid wasted bits')
        if typ==0:
            val=br.read_signed(eff); out=[val]*blocksize
        elif typ==1:
            out=[br.read_signed(eff) for _ in range(blocksize)]
        elif 8 <= typ <= 12:
            order=typ-8; warm=[br.read_signed(eff) for _ in range(order)]; resid=self._read_residual(br,blocksize,order); out=list(warm)
            for r in resid:
                if order==0: pred=0
                elif order==1: pred=out[-1]
                elif order==2: pred=2*out[-1]-out[-2]
                elif order==3: pred=3*out[-1]-3*out[-2]+out[-3]
                else: pred=4*out[-1]-6*out[-2]+4*out[-3]-out[-4]
                out.append(pred+r)
        elif typ>=32:
            order=typ-31; warm=[br.read_signed(eff) for _ in range(order)]
            prec_minus1=br.read(4)
            if prec_minus1==15: raise ValueError('invalid coeff precision')
            prec=prec_minus1+1; shift=br.read_signed(5); coeffs=[br.read_signed(prec) for _ in range(order)]
            resid=self._read_residual(br,blocksize,order); out=list(warm)
            if shift>=0:
                for r in resid:
                    pred=(sum(coeffs[i]*out[-1-i] for i in range(order))>>shift); out.append(pred+r)
            else:
                for r in resid:
                    pred=(sum(coeffs[i]*out[-1-i] for i in range(order))<<(-shift)); out.append(pred+r)
        else:
            raise ValueError(f'invalid subframe type {typ}')
        if wasted:
            out=[v<<wasted for v in out]
        return out
    def packets_and_frames(self):
        """Yield (raw_frame_bytes, info_dict, planar_samples_in_flac_bps_range)"""
        data=self.data; br=BitReader(data,self.frames_start); info=self.info
        frames=[]
        # We need to know frame boundaries; decode frames sequentially with BitReader tracking byte positions
        while br.pos < len(data)*8:
            start_byte=br.pos//8
            # skip possible zero padding at EOF
            if start_byte>=len(data): break
            # If remaining bytes are all zero, stop (trailing junk not parsed)
            if all(b==0 for b in data[start_byte:]): break
            frame_start_bit=br.pos
            try:
                sync=br.read(14)
                if sync != 0x3ffe:
                    raise ValueError('invalid frame sync')
                br.read(1); blocking=br.read(1); bscode=br.read(4); srcode=br.read(4); chassign=br.read(4); sscode=br.read(3); br.read(1)
                framenum=br.read_utf8()
                if bscode==0:
                    bs=info.min_blocksize if info else 0
                elif bscode==1: bs=192
                elif 2<=bscode<=5: bs=576*(1<<(bscode-2))
                elif bscode==6: bs=br.read(8)+1
                elif bscode==7: bs=br.read(16)+1
                else: bs=256*(1<<(bscode-8))
                # sample rate code
                sr_table={0:info.sample_rate if info else 0,1:88200,2:176400,3:192000,4:8000,5:16000,6:22050,7:24000,8:32000,9:44100,10:48000,11:96000}
                if srcode in sr_table: sr=sr_table[srcode]
                elif srcode==12: sr=br.read(8)*1000
                elif srcode==13: sr=br.read(16)
                elif srcode==14: sr=br.read(16)*10
                elif srcode==15: raise ValueError('invalid sample rate code')
                crc8_read=br.read(8)
                header_end_byte=br.byte_pos(); header_bytes=data[start_byte:header_end_byte-1]
                crc_ok = (crc8(header_bytes)==crc8_read)
                # channels / bps
                if chassign<=7:
                    nch=chassign+1; bps_list=[]
                    base_bps=info.bps if info else 16
                    if sscode!=0:
                        mp={1:8,2:12,4:16,5:20,6:24,7:32}; base_bps=mp.get(sscode,base_bps)
                    bps_list=[base_bps]*nch; mode='indep'
                elif chassign in (8,9,10):
                    nch=2; base_bps=info.bps if info else 16
                    if sscode!=0:
                        mp={1:8,2:12,4:16,5:20,6:24,7:32}; base_bps=mp.get(sscode,base_bps)
                    if chassign==8: bps_list=[base_bps,base_bps+1]; mode='left_side'
                    elif chassign==9: bps_list=[base_bps+1,base_bps]; mode='right_side'
                    else: bps_list=[base_bps,base_bps+1]; mode='mid_side'
                else: raise ValueError('invalid channel assignment')
                decoded=[]
                for c in range(nch):
                    decoded.append(self._decode_subframe(br,bs,bps_list[c]))
                br.align_byte(); crc16_read=br.read(16); end_byte=br.byte_pos(); raw=data[start_byte:end_byte]
                crc_ok = crc_ok and (crc16(raw[:-2])==crc16_read)
                # channel decorrelation
                if chassign<=7:
                    chans=decoded
                elif chassign==8:
                    L=decoded[0]; S=decoded[1]; chans=[L,[l-s for l,s in zip(L,S)]]
                elif chassign==9:
                    S=decoded[0]; R=decoded[1]; chans=[[s+r for s,r in zip(S,R)],R]
                else:
                    chans=[[],[]]
                    for m,s in zip(decoded[0],decoded[1]):
                        mid=((m<<1) | (s & 1)); left=(mid+s)>>1; right=(mid-s)>>1; chans[0].append(left); chans[1].append(right)
                frames.append((raw, {'blocksize':bs,'sample_rate':sr,'channels':len(chans),'bps':base_bps,'chassign':chassign,'frame_number':framenum,'crc_ok':crc_ok}, chans))
            except Exception as e:
                # Attach partial info and re-raise as decode error with context
                raise ValueError(f'FLAC frame decode error at byte {start_byte}: {e}')
        return frames

def decode_flac_data(data):
    dec=FlacDecoder(data); frames=dec.packets_and_frames()
    info=dec.info; chans_count=info.channels if info else (len(frames[0][2]) if frames else 1)
    planar=[[] for _ in range(chans_count)]
    for raw,meta,chans in frames:
        for i in range(chans_count): planar[i].extend(chans[i] if i < len(chans) else [0]*meta['blocksize'])
    return dec, frames, planar

# -------- FLAC encoding --------
ALLOWED_BLOCKSIZES=[192,256,512,576,1024,1152,2048,2304,4096,4608,8192,16384,32768]
def select_blocksize(sample_rate, compression_level, frame_size):
    if frame_size and frame_size>0:
        return frame_size
    lvl=5 if compression_level is None or compression_level<0 else compression_level
    if lvl<=2:
        target=(sample_rate*27)//1000
    else:
        target=(sample_rate*105)//1000
    chosen=192
    for b in ALLOWED_BLOCKSIZES:
        if b<=target: chosen=b
        else: break
    return chosen

@dataclass
class FlacOptions:
    compression_level:int=-1
    lpc_type:int=-1  # 0 none 1 fixed 2 levinson 3 cholesky
    lpc_coeff_precision:int=15
    lpc_passes:int=2
    min_partition_order:int=-1
    max_partition_order:int=-1
    prediction_order_method:int=-1
    ch_mode:int=-1
    exact_rice_parameters:bool=False
    multi_dim_quant:bool=False
    min_prediction_order:int=-1
    max_prediction_order:int=-1
    frame_size:int=0

LEVEL_TABLE={
    # level: dict of defaults (deduced empirically; see notes in code comments)
    0: dict(lpc_type=1, min_prediction_order=2, max_prediction_order=3, prediction_order_method=0, min_partition_order=2, max_partition_order=2),
    1: dict(lpc_type=1, min_prediction_order=0, max_prediction_order=4, prediction_order_method=0, min_partition_order=2, max_partition_order=2),
    2: dict(lpc_type=1, min_prediction_order=0, max_prediction_order=4, prediction_order_method=0, min_partition_order=0, max_partition_order=0),
    3: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=6, prediction_order_method=4),
    4: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=0),
    5: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=0),
    6: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=0),
    7: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=4),
    8: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=0),
    9: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=4),
    10: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=4),
    11: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=32, prediction_order_method=4),
    12: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=32, prediction_order_method=4),
}

class FlacEncoderError(ValueError):
    pass

class FlacEncoder:
    def __init__(self, sample_rate, channels, sample_fmt, options:FlacOptions, user_set=None):
        self.sample_rate=int(sample_rate); self.channels=int(channels); self.sample_fmt=sample_fmt
        self.user_set=set(user_set or [])
        o=options; self.raw_options=o
        # Determine compression level
        lvl=o.compression_level
        if lvl is None or lvl<0: lvl_eff=5
        else: lvl_eff=lvl
        if lvl_eff>12:
            raise FlacEncoderError('invalid compression level')
        self.level=lvl_eff
        defaults=LEVEL_TABLE.get(lvl_eff,{})
        def resolve(fieldname, sentinel=-1):
            val=getattr(o,fieldname)
            if val==sentinel:
                return defaults.get(fieldname, val)
            return val
        self.lpc_type=resolve('lpc_type')
        if self.lpc_type==-1: self.lpc_type=2
        self.min_prediction_order=resolve('min_prediction_order')
        self.max_prediction_order=resolve('max_prediction_order')
        if self.min_prediction_order==-1: self.min_prediction_order=1
        if self.max_prediction_order==-1: self.max_prediction_order=8
        # fixed clamping in validation mimics ffmpeg: for fixed type, min/max are clamped to <=4 for validation/message purposes
        # We keep raw values for error reporting in caller where needed; here validate:
        eff_min=self.min_prediction_order; eff_max=self.max_prediction_order
        if self.lpc_type==1:
            eff_min=min(eff_min,4); eff_max=min(eff_max,4)
        if eff_min>eff_max:
            # caller formats the exact ffmpeg message using these effective values
            raise FlacEncoderError(f'invalid prediction orders: min={eff_min} max={eff_max}')
        self.prediction_order_method=resolve('prediction_order_method')
        if self.prediction_order_method==-1: self.prediction_order_method=0
        self.lpc_coeff_precision=o.lpc_coeff_precision
        self.lpc_passes=o.lpc_passes
        self.exact_rice_parameters=bool(o.exact_rice_parameters)
        self.multi_dim_quant=bool(o.multi_dim_quant)
        self.ch_mode=o.ch_mode
        # Partition orders: sentinel handling with ffmpeg bug emulation is done by caller validation;
        # effective values if not set come from level table if present else 0..8
        self.min_partition_order_raw=o.min_partition_order; self.max_partition_order_raw=o.max_partition_order
        if o.min_partition_order!=-1 and o.max_partition_order==-1:
            raise FlacEncoderError(f'invalid partition orders: min={o.min_partition_order} max=-1')
        self.min_partition_order = defaults.get('min_partition_order',0) if o.min_partition_order==-1 else o.min_partition_order
        self.max_partition_order = defaults.get('max_partition_order',8) if o.max_partition_order==-1 else o.max_partition_order
        if self.min_partition_order>self.max_partition_order:
            raise FlacEncoderError(f'invalid partition orders: min={self.min_partition_order} max={self.max_partition_order}')
        if sample_fmt in ('s16','s16p'):
            self.bps=16
        elif sample_fmt in ('s32','s32p'):
            self.bps=24
        else:
            raise FlacEncoderError(f'unsupported sample format {sample_fmt} for flac encoder')
        if self.channels<1 or self.channels>8:
            raise FlacEncoderError('invalid number of channels for FLAC')
        if self.sample_rate<=0 or self.sample_rate>655350*2:
            # FLAC supports up to 1048575 Hz in streaminfo (20 bits); ffmpeg checks subset limits in some cases
            if self.sample_rate<=0: raise FlacEncoderError('invalid sample rate')
        self.blocksize=select_blocksize(self.sample_rate, o.compression_level, o.frame_size)
        if self.blocksize<16 and False:
            pass
        self.max_frame_size=get_max_frame_size(self.blocksize,self.channels,self.bps)
        # FLAC channel layout support warning handled by caller (needs layout tokens)
    def initial_streaminfo(self):
        return FlacStreamInfo(self.blocksize,self.blocksize,0,self.max_frame_size,self.sample_rate,self.channels,self.bps,0,b'\x00'*16)
    # ----- internal helpers -----
    def _windowed(self, seq):
        N=len(seq); out=[0.0]*N
        for i,x in enumerate(seq):
            if N%2==1 and i==N//2:
                out[i]=0.0
            else:
                d=i+1 if i < N-i else N-i
                w=d*d-1-4*d/N
                out[i]=x*w
        return out
    def _lpc_coeffs(self, seq, min_order, max_order):
        # Returns (order, coeffs_list_float, refs)
        max_order=max(0,min(max_order,32,len(seq)-1 if len(seq)>0 else 0))
        if max_order<=0:
            return 0,[],[]
        s=self._windowed(seq); N=len(seq)
        # autocorr
        autoc=[]
        for k in range(max_order+1):
            # sum(s[i]*s[i+k])
            total=0.0
            # local variables for speed
            for i in range(N-k):
                total += s[i]*s[i+k]
            autoc.append(total)
        if autoc[0]==0 or not math.isfinite(autoc[0]):
            ord_eff=max(min_order,1)
            return ord_eff,[0.0]*ord_eff,[0.0]*max_order
        a=[0.0]*max_order; e=autoc[0]; refs=[]; by_order={}
        for i in range(max_order):
            if e==0 or not math.isfinite(e):
                refs.append(0.0); by_order[i+1]=a[:i+1]; continue
            acc=autoc[i+1]
            # acc -= sum a_j * autoc[i-j]
            ssum=0.0
            for j in range(i): ssum += a[j]*autoc[i-j]
            acc -= ssum
            alpha=acc/e; refs.append(alpha)
            an=a[:]; an[i]=alpha
            for j in range(i): an[j]=a[j]-alpha*a[i-1-j]
            a=an; by_order[i+1]=a[:i+1]
            e *= (1-alpha*alpha)
            if e<=0:
                # fill rest with zeros refs
                for ii in range(i+1,max_order):
                    refs.append(0.0); by_order[ii+1]= (by_order.get(ii, a[:ii])+[0.0])[:ii+1] if ii>0 else [0.0]
                break
        # order selection
        method=self.prediction_order_method
        if method==0:  # estimation
            order=min_order if min_order>0 else 1
            for i,r in enumerate(refs,1):
                if abs(r)>0.1: order=i
            order=max(min_order, min(order,max_order))
            if order<=0: order=1
        elif method in (1,2,3,4,5):
            order=self._search_order(seq, by_order, min_order, max_order, method)
        else:
            order=min_order
        return order, by_order.get(order,[0.0]*order), refs
    def _quantize(self, coeffs, precision):
        if not coeffs:
            return 0,[]
        if precision<=1:
            return 0,[0]*len(coeffs)
        maxabs=max(abs(x) for x in coeffs)
        if maxabs==0 or not math.isfinite(maxabs):
            return 0,[0]*len(coeffs)
        max_coef=(1<<(precision-1))-1
        shift=int(math.floor(math.log2(max_coef/maxabs))) if maxabs>0 else 15
        # FLAC shift field is 5-bit signed; ffmpeg seems to clamp between 0 and 15 in most paths we observed.
        shift=max(0,min(15,shift))
        # If after clamping to 0 a coefficient still overflows, clipping below handles it.
        q=[]
        lo=-(1<<(precision-1)); hi=(1<<(precision-1))-1
        for x in coeffs:
            v=int(round(x*(1<<shift)))
            if v<lo: v=lo
            elif v>hi: v=hi
            q.append(v)
        return shift,q
    def _search_order(self, seq, by_order, min_order, max_order, method):
        # Evaluate a subset of orders according to method using estimated bits with quantized coeffs
        def eval_order(o):
            if o<=0: return float('inf')
            coeffs=by_order.get(o)
            if coeffs is None: return float('inf')
            shift,q=self._quantize(coeffs,self.lpc_coeff_precision)
            resid=[]
            for idx in range(o,len(seq)):
                pred=sum(q[j]*seq[idx-j-1] for j in range(o))>>shift; resid.append(seq[idx]-pred)
            bits,_params,_porder=self._rice_bits_estimate(resid,o,len(seq),16)  # bps placeholder for method choice in bits function; rate only weakly depends
            return bits + o*self.lpc_coeff_precision + o*16
        if method==4:  # search all
            candidates=list(range(max(min_order,1),max_order+1))
        elif method==5: # log: binary-ish search; approximate as search among a log-spaced set refined; for now search all (behaves close in many cases)
            candidates=list(range(max(min_order,1),max_order+1))
        elif method in (1,2,3):
            step={1:2,2:4,3:8}[method]
            # evaluate orders in steps then refine around the best (approximation of multi-level search in lpc.c)
            cand=list(range(max(min_order,1),max_order+1,step))
            if cand and cand[-1]!=max_order: cand.append(max_order)
            scored=[(eval_order(o),o) for o in cand]; best_o=min(scored)[1]
            lo=max(max(min_order,1),best_o-step+1); hi=min(max_order,best_o+step-1)
            candidates=list(range(lo,hi+1))
        else:
            candidates=list(range(max(min_order,1),max_order+1))
        best=None; besto=max(min_order,1)
        for o in candidates:
            b=eval_order(o)
            if best is None or b<best: best=b; besto=o
        return besto
    @staticmethod
    def _fixed_residual(seq,order):
        out=[]
        for i in range(order,len(seq)):
            x=seq[i]
            if order==0: r=x
            elif order==1: r=x-seq[i-1]
            elif order==2: r=x-2*seq[i-1]+seq[i-2]
            elif order==3: r=x-3*seq[i-1]+3*seq[i-2]-seq[i-3]
            elif order==4: r=x-4*seq[i-1]+6*seq[i-2]-4*seq[i-3]+seq[i-4]
            else: r=x
            out.append(r)
        return out
    @staticmethod
    def _est_k(cnt,sumu,max_param):
        if cnt<=0: return 0
        adj=(sumu-(cnt>>1))//cnt if sumu>(cnt>>1) else 0
        if adj<=0: return 0
        k=int(math.floor(math.log2(adj)))
        return max(0,min(max_param,k))
    def _rice_bits_estimate(self,resid,order,blocksize,eff_bps):
        method=1 if eff_bps>16 else 0; pbits=5 if method else 4; max_param=30 if method else 14
        # allowed porder range
        max_allowed=0
        for p in range(8,-1,-1):
            if blocksize % (1<<p)==0 and (blocksize>>p) > order:
                max_allowed=p; break
        max_p=min(self.max_partition_order,max_allowed)
        min_p=min(self.min_partition_order,max_p)
        # Precompute prefix sums of u for sum_shift estimates and lists for exact
        ulist=[(2*r if r>=0 else -2*r-1) for r in resid]
        pref=[0]
        for u in ulist: pref.append(pref[-1]+u)
        best=None; best_params=None; best_p=min_p
        for porder in range(min_p,max_p+1):
            partsize=blocksize>>porder; total=2+4; params=[]; idx=0; ok=True
            for part_idx in range(1<<porder):
                cnt=partsize-order if part_idx==0 else partsize
                if cnt<0: ok=False; break
                sumu=pref[idx+cnt]-pref[idx]
                if self.exact_rice_parameters:
                    # exact search
                    seg=ulist[idx:idx+cnt]; bestk=0; bestb=None
                    for kk in range(max_param+1):
                        bb=0
                        for u in seg: bb += (u>>kk)+1+kk
                        if bestb is None or bb<bestb: bestb=bb; bestk=kk
                    k=bestk; total += pbits + bestb
                else:
                    k=self._est_k(cnt,sumu,max_param); total += pbits + cnt*(k+1) + (sumu>>k)
                params.append(k); idx+=cnt
            if not ok: continue
            if best is None or total<best:
                best=total; best_params=params; best_p=porder
        return best,best_params,best_p
