                    if chassign==8: bps_list=[base_bps,base_bps+1]; mode='left_side'
                    elif chassign==9: bps_list=[base_bps+1,base_bps]; mode='right_side'
                    else: bps_list=[base_bps,base_bps+1]; mode='mid_side'
