    5: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=0),
    6: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=0),
    7: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=8, prediction_order_method=4),
    8: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=0),
    9: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=4),
    10: dict(lpc_type=2, min_prediction_order=1, max_prediction_order=12, prediction_order_method=4),
