    def _fixed_residual(seq,order):
        out=[]
        for i in range(order,len(seq)):
            x=seq[i]
            if order==0: r=x
            elif order==1: r=x-seq[i-1]
            elif order==2: r=x-2*seq[i-1]+seq[i-2]
            elif order==3: r=x-3*seq[i-1]+3*seq[i-2]-seq[i-3]
            elif order==4: r=x-4*seq[i-1]+6*seq[i-2]-4*seq[i-3]+seq[i-4]
            else: r=x
            out.append(r)
        return out
