    def _est_k(cnt,sumu,max_param):
        if cnt<=0: return 0
        adj=(sumu-(cnt>>1))//cnt if sumu>(cnt>>1) else 0
        if adj<=0: return 0
        k=int(math.floor(math.log2(adj)))
        return max(0,min(max_param,k))
