            candidates=list(range(max(min_order,1),max_order+1))
        elif method==5: # log: binary-ish search; approximate as search among a log-spaced set refined; for now search all (behaves close in many cases)
            candidates=list(range(max(min_order,1),max_order+1))
        elif method in (1,2,3):
            step={1:2,2:4,3:8}[method]
