        has = False
        if rest.startswith('<') or rest.startswith('[:'):
            has = True
        # Options in AVOption-style global sections have no placeholder; leave manual/global fallbacks.
        if name not in _parsed_specs:
            _parsed_specs[name] = OptSpec(name, has, 'file', False, True)
    # avoption names from help_full
    names=set()
    try:
        full = get_static('help_full').decode('utf-8','replace')
        for line in full.splitlines():
            m = re.match(r'^  -([A-Za-z0-9_][A-Za-z0-9_.-]*)', line)
            if m: names.add(m.group(1))
    except Exception:
        pass
