def find_option(token_name):
    """Return (spec, specifier) or (None,None). token_name is argv token without leading '-'."""
    _parse_option_specs()
    if token_name in MANUAL_SPECS:
        return MANUAL_SPECS[token_name], None
    # literal name in parsed specs
    if token_name in _parsed_specs:
        return _parsed_specs[token_name], None
    # negation of a bool manual/parsed option: -no<name>
    if token_name.startswith('no') and len(token_name)>2:
        base = token_name[2:]
        if base in MANUAL_SPECS and not MANUAL_SPECS[base].has_arg:
            s = OptSpec(token_name, False, MANUAL_SPECS[base].kind, False, MANUAL_SPECS[base].allow_spec); return s, None
        if base in _parsed_specs and not _parsed_specs[base].has_arg:
            s = OptSpec(token_name, False, 'file', False, True); return s, None
    # with stream specifier
    if ':' in token_name:
        base, spec = token_name.split(':',1)
        if base in MANUAL_SPECS and MANUAL_SPECS[base].allow_spec:
            return MANUAL_SPECS[base], spec
        if base in _parsed_specs:
            return _parsed_specs[base], spec
        if base in _avoption_names:
            # generic codec/format option with specifier; accepted for many encoder options
            return OptSpec(base, True, 'file', False, True), spec
        return None, None
    if token_name in _avoption_names:
        return OptSpec(token_name, True, 'file', False, False), None
    return None, None

