def split_arguments(argv):
    """Returns (global_options, inputs, outputs, trailing_options) following our approximation of ffmpeg splitting."""
    globals_=[]; inputs=[]; outputs=[]; pending=[]; trailing=[]
    i=0; force_file=False
    while i < len(argv):
        arg = argv[i]
        if force_file:
            outputs.append(FileGroup('output', arg, pending)); pending=[]; force_file=False; i+=1; continue
        if arg == '--':
            # Next token (if any) is forced as a file argument; if none, ignore the token.
            force_file=True; i+=1
            if i>=len(argv):
                force_file=False
            continue
        if arg == '-i':
            # handled below as an option-like delimiter
            if i+1>=len(argv):
                raise SplitError(["Missing argument for option 'i'.", "Error splitting the argument list: Invalid argument"], 234)
            inputs.append(FileGroup('input', argv[i+1], pending)); pending=[]; i+=2; continue
        if len(arg)>=1 and arg[0]=='-' and arg!='-':
            token_name = arg[1:]
            spec, stream_spec = find_option(token_name)
            if spec is None:
                # name for error: ffmpeg strips exactly one leading dash
                shown = arg[1:]
                raise SplitError([f"Unrecognized option '{shown}'.", "Error splitting the argument list: Option not found"], 8)
            value=None
            if spec.name == 'i':
                # shouldn't happen as handled above, but keep
                pass
            if getattr(spec,'optional_arg',False):
                if i+1 < len(argv):
                    value=argv[i+1]; i+=1
                else:
                    value=None
            elif spec.has_arg:
                if i+1>=len(argv):
                    shown=spec.name
                    raise SplitError([f"Missing argument for option '{shown}'.", "Error splitting the argument list: Invalid argument"], 234)
                value=argv[i+1]; i+=1
            opt=Option(spec.name, spec, stream_spec, value, arg)
            if spec.kind in ('global','exit'):
                globals_.append(opt)
            else:
                pending.append(opt)
            i+=1; continue
        else:
            outputs.append(FileGroup('output', arg, pending)); pending=[]; i+=1; continue
    trailing=pending
    return globals_, inputs, outputs, trailing

def parse_loglevel_value(s):
    # Returns (level, flags set) or raises ValueError
    if s is None: raise ValueError('')
    parts=str(s).split('+')
    level=None; flags=set()
    for part in parts:
        if part in ('repeat','level','time','datetime'):
            flags.add(part)
        elif part in LOG_LEVELS:
