def codec_string_audio(codec, tag, audio, is_output=False, bit_rate_override=None):
    # tag string like ([1][0][0][0] / 0x0001)
    parts=[]
    if codec:
        parts.append(codec)
    if tag is not None and tag!=0:
        # For flac input codec tag is 0 so omitted.
        b = tag.to_bytes(4,'little') if isinstance(tag,int) else bytes(tag)
        def byte_repr(x):
            return f"[{x}]"
        tagstr=''.join(byte_repr(x) for x in b)+f" / 0x{tag:04x}" if isinstance(tag,int) else ''
        parts[0] = f"{codec} ({tagstr})"
    s=f"{parts[0]}, {audio.sample_rate} Hz, {audio.layout_name}, {audio.sample_fmt}"
    # (24 bit) annotation when bits_per_raw differs from sample fmt bits and sample fmt is s32/s16
    fmt_bits = {'s16':16,'s32':32,'s16p':16,'s32p':32}.get(audio.sample_fmt)
    if fmt_bits and audio.bits_per_raw_sample and audio.bits_per_raw_sample!=fmt_bits:
        s+=f" ({audio.bits_per_raw_sample} bit)"
    # bitrate
    br=bit_rate_override
    if br is None:
        if codec and codec.startswith('pcm_'):
            bits = {'pcm_u8':8,'pcm_s16le':16,'pcm_s16be':16,'pcm_s24le':24,'pcm_s24be':24,'pcm_s32le':32,'pcm_s32be':32,'pcm_f32le':32,'pcm_f64le':64,'pcm_alaw':8,'pcm_mulaw':8,'pcm_s8':8}.get(codec,16)
            br=audio.sample_rate*audio.channels*bits
        elif codec=='flac' and not is_output:
            br=0
        elif codec=='flac' and is_output:
            br=128000
    if br:
        s+=f", {int(br)//1000} kb/s"
    return s

def dump_input(opened):
    idx=opened.group.index if hasattr(opened.group,'index') else opened.index
    logger.log(32, f"Input #{idx}, {opened.format_name}, from '{opened.group.filename}':\n")
