def get_option(opts, names, default=None, spec_filter=None):
    """Return last value for any option name in names from an options list. If spec_filter is provided, it is a function(stream_spec)->bool"""
    val=default
    for o in opts:
        if o.name in names:
            if spec_filter is not None and not spec_filter(o.stream_spec):
                continue
            val=o.value
    return val

