def spec_matches_audio(spec, stream_index=0, audio_index=0):
    if spec is None or spec=='':
        return True
    # spec can be like 'a', 'a:0', '0', 'v', 's', 'a:1', '0:a:0' (for some options specified in a full form - not typical for output options)
    parts=str(spec).split(':')
    # Normalize: last elements that describe stream
    if parts[0] in ('a','v','s','d','t'):
        if parts[0]!='a': return False
        if len(parts)>1:
            try: return int(parts[1])==audio_index
            except Exception: return True
        return True
    if parts[0].isdigit():
        if len(parts)==1:
            return int(parts[0])==stream_index
        # form file_index:stream_type:stream_index is used for -map values not option specifiers typically
        return True
    return True

