def read_input_bytes(filename, input_index, in_ctx_obj):
    # Returns bytes for seekable regular inputs / stdin
    if filename=='-' or filename.startswith('pipe:'):
        return sys.stdin.buffer.read()
    path=filename
    if path.startswith('file://'):
        path=path[7:]
    elif path.startswith('file:'):
        path=path[5:]
    try:
        with open(path,'rb') as f:
            return f.read()
    except OSError as e:
        err=os.strerror(e.errno) if e.errno else str(e)
        logger.log(16, f"Error opening input: {err}\n", context=ctx(in_ctx_obj, f"in#{input_index}"))
