    ext=os.path.splitext(filename)[1].lower().lstrip('.')
    extmap={'wav':'wav','wave':'wav','flac':'flac','ogg':'ogg','oga':'ogg','aif':'aiff','aiff':'aiff','au':'au','caf':'caf'}
    return extmap.get(ext)

