        planar=[[int(x)<<shift for x in ch] for ch in planar_bps]
        audio=AudioData(info.sample_rate,layout,tokens,sample_fmt,planar,info.bps,meta)
        stream=InputStreamInfo(index=0,file_index=index,codec='flac',codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name='flac',guessed=False,extradata=info.to_bytes(),flac_info=info)
