_known_demuxers=None
def _known_demuxer_names():
    global _known_demuxers
    if _known_demuxers is not None: return _known_demuxers
    names=set()
    try:
        txt=get_static('demuxers').decode()
        for line in txt.splitlines():
            m=re.match(r'^ [A-Za-z. ]{2} +(\S+)',line)
            if m:
                for n in m.group(1).split(','): names.add(n)
    except Exception: pass
    names.update(RAW_PCM_FORMATS.keys())
    _known_demuxers=names; return names

def make_pcm_packets(audio, codec, group=None):
    # Segment decoded audio into packets as PCM demuxer/decoder would for framecrc/framemd5 purposes.
    # Data bytes will be regenerated later from audio segments by packet data generation functions in hash paths.
    ps=pcm_packet_samples(audio.sample_rate)
    packets=[]; pos=0
    while pos<audio.nb_samples:
        dur=min(ps,audio.nb_samples-pos); packets.append({'duration':dur,'pts':pos,'start':pos,'codec':codec}); pos+=dur
    if audio.nb_samples==0:
        packets=[]
    return packets

def open_raw_pcm_input(group,index,in_obj,data,fmt):
    codec,sample_fmt,cont_bytes,fmtcode = RAW_PCM_FORMATS[fmt]
    # sample rate and layout from input options: -ar/-sample_rate, -ac/-ch_layout/-channel_layout
    sr_val=get_option(group.options,['sample_rate','ar'])
    sr=parse_rate_value(sr_val) if sr_val is not None else 44100
    # Note: -ar as an *input* option in ffmpeg for raw formats is interpreted by the demuxer? The CLI maps input -ar to codecpar sample_rate for raw.
    layout_val=get_option(group.options,['ch_layout','channel_layout'])
    ac_val=get_option(group.options,['ac'])
    if layout_val is not None:
        parsed=parse_layout(str(layout_val))
        if not parsed:
            # message observed for input ch_layout errors is in input stream context; simplify
            raise FfmpegStageError('input',group.filename,'Invalid argument',234)
        layout,tokens=parsed; channels=len(tokens)
    elif ac_val is not None:
        channels=int(parse_rate_value(ac_val)); layout,tokens=default_layout(channels)
    else:
        channels=1; layout,tokens='mono',['FC']
    frames=len(data)//(cont_bytes*channels) if channels else 0
    planar=[[] for _ in range(channels)]
    raw=data[:frames*cont_bytes*channels]
    if fmtcode:
        vals=struct.unpack(('<' if cont_bytes>1 and fmt not in ('s16be','s24be','s32be','f32be','f64be','u16be','u32be') else '')+f"{len(raw)//cont_bytes}{fmtcode[-1]}",raw) if False else None
    # simpler per format decode
    if fmt in ('s24le','s24be','u24le','u24be'):
        be=fmt.endswith('be'); signed=fmt.startswith('s')
        for i in range(frames*channels):
            chunk=raw[i*3:i*3+3]; v=int.from_bytes(chunk,'big' if be else 'little',signed=signed)
            if sample_fmt=='s32': v = v<<8 if signed else (v<<8)
            planar[i%channels].append(v)
    elif fmt in ('alaw','mulaw'):
        fn=wav_io.alaw_to_linear if fmt=='alaw' else wav_io.mulaw_to_linear
        for i,b in enumerate(raw): planar[i%channels].append(fn(b))
    else:
        # struct code char from fmtcode
        code=RAW_PCM_FORMATS[fmt][3]; prefix='>' if fmt.endswith('be') else '<'
        if fmt in ('s8','u8'): prefix=''
        vals=struct.unpack(f"{prefix}{len(raw)//cont_bytes}{code}",raw)
        # adjustments for decoders output sample formats:
        # pcm_u16 -> decoder outputs s16? value conversion: (u-32768). pcm_s8 dec outputs s16 with value<<8? Check later; for raw hash copy we use packets data separately.
        vals=list(vals)
        if fmt in ('u16le','u16be'):
            vals=[v-32768 for v in vals]
        elif fmt in ('u32le','u32be'):
            vals=[v-2147483648 for v in vals]
        elif fmt=='s8':
            vals=[v<<8 for v in vals]
        for i,v in enumerate(vals): planar[i%channels].append(v)
    bits_raw={'s16':16,'s32':32,'flt':32,'dbl':64,'u8':8,'s64':64}.get(sample_fmt,16)
    if fmt in ('s24le','s24be'): bits_raw=24
    audio=AudioData(sr,layout,tokens,sample_fmt,planar,bits_raw,[])
    logger.log(32, "Estimating duration from bitrate, this may be inaccurate\n", context=ctx(in_obj,f"in#{index}/{fmt}"))
    stream=InputStreamInfo(index=0,file_index=index,codec=codec,codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name=fmt)
    stream.input_ctx=in_obj
    stream.packets=make_pcm_packets(audio,codec,group)
    # attach raw bytes to packets for copy/hash paths
    bps_bytes=cont_bytes*channels
    for p in stream.packets:
        st=p['start']*bps_bytes; p['data']=raw[st:st+p['duration']*bps_bytes]
    dur_us=duration_us_from_samples(frames,sr) if frames>0 else None
    bits_codec={'pcm_u8':8,'pcm_s16le':16,'pcm_s16be':16,'pcm_s24le':24,'pcm_s32le':32,'pcm_f32le':32,'pcm_f64le':64}.get(codec,16)
    br=sr*channels*bits_codec
    if dur_us:
        br=(len(data)*8*1000000)//dur_us if len(data) else br
        # Observed raw dump bitrate for a small partial file was 705 kb/s for s16 (stream bitrate) when file only 8820 and duration exact gives same - for tiny 4000 bytes f32 it gave 1412 kb/s (~codec bitrate +). The stream-line bitrate is handled separate; file bitrate should approximate filesize/duration.
    opened=InputFileOpened(group=group,format_name=fmt,metadata=[],streams=[stream],duration_us=dur_us,file_size=len(data),bit_rate=int(br))
    opened.index=index; opened.ctx=in_obj
    return opened

def open_lavfi_input(group,index,in_obj):
    graph=group.filename
    # Support simple graphs with a single audio source filter and optional simple filters separated by commas
    # Tokenize by commas not inside quotes/brackets (simple)
    parts=[]; cur=''; depth=0; quote=None
    for ch in graph:
        if quote:
            cur+=ch
            if ch==quote: quote=None
        elif ch in ("'",'"'):
            quote=ch; cur+=ch
        elif ch=='[': depth+=1; cur+=ch
        elif ch==']': depth-=1; cur+=ch
        elif ch==',' and depth==0:
            parts.append(cur); cur=''
        else: cur+=ch
    if cur: parts.append(cur)
    if not parts:
        raise FfmpegStageError('input',graph,'Invalid argument',234)
    # first part should be source like sine=... or anullsrc=...; allow a leading label [out] etc ignored crudely
    audio=None; source_name=None
    for idx,part in enumerate(parts):
        p=part.strip()
        # strip link labels at start/end like [in]sine...[out]
        p=re.sub(r'^\[[^\]]+\]','',p); p=re.sub(r'\[[^\]]+\]$','',p)
        if '=' in p:
            fname,argstr=p.split('=',1)
        else:
            fname,argstr=p,''
        fname=fname.strip()
        if idx==0:
            audio=generate_lavfi_source(fname,argstr)
            source_name=fname
            if audio is None:
                logger.log(16, f"Unknown filter '{fname}'\n", context=ctx(in_obj,f"in#{index}/lavfi"))
                raise FfmpegStageError('input',graph,'Filter not found',8)
        else:
            audio=apply_audio_filter(audio,fname,argstr)
            if audio is None:
                logger.log(16, f"Unknown filter '{fname}'\n", context=ctx(in_obj,f"in#{index}/lavfi"))
                raise FfmpegStageError('input',graph,'Filter not found',8)
