    codecmap={'s16':'pcm_s16le','s32':'pcm_s32le','flt':'pcm_f32le','fltp':'pcm_f32le','dbl':'pcm_f64le','dblp':'pcm_f64le','u8':'pcm_u8'}
    codec=codecmap.get(audio.sample_fmt,'pcm_s16le')
    # In observed sine, stream format was s16 (the lavfi graph negotiates to s16 because sine source outputs s16)
    stream=InputStreamInfo(index=0,file_index=index,codec=codec,codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name='lavfi')
    stream.input_ctx=in_obj
    stream.packets=make_pcm_packets(audio,codec,group)
    # start 0 in dump for lavfi:
    dur_us=None
    opened=InputFileOpened(group=group,format_name='lavfi',metadata=[],streams=[stream],duration_us=dur_us,file_size=None,bit_rate=audio.sample_rate*audio.channels*16)
    opened.index=index; opened.ctx=in_obj; opened.start_time_us=0
    return opened

def parse_filter_args(argstr):
    args=[]; kwargs={}
    if not argstr: return args,kwargs
    # split by ':' not escaped / quoted (simple)
    parts=[]; cur=''; quote=None
    for ch in argstr:
        if quote:
            cur+=ch
            if ch==quote: quote=None
        elif ch in ("'",'"'):
            quote=ch; cur+=ch
        elif ch==':':
            parts.append(cur); cur=''
        else: cur+=ch
    if cur or argstr.endswith(':'): parts.append(cur)
    for p in parts:
        p=p.strip()
        if '=' in p:
            k,v=p.split('=',1); kwargs[k.strip()]=v.strip().strip("'\"")
        elif p:
            args.append(p.strip("'\""))
    return args,kwargs

def generate_lavfi_source(fname,argstr):
    args,kw=parse_filter_args(argstr)
    if fname=='sine':
        freq=float(kw.get('frequency',kw.get('f',440)))
        sr=int(float(kw.get('sample_rate',kw.get('r',44100))))
        dur_s=kw.get('duration',kw.get('d'))
        nsamples=None
        if dur_s is not None:
            try: secs=parse_time_value(dur_s)
            except Exception: secs=float(dur_s)
            nsamples=int(round(secs*sr))
        # beep_factor ignored for now (adds a beep each second if set)
        # If no duration, lavfi duration is infinite; callers may use -t output to limit. We need a finite default for standalone generation paths.
        # ffmpeg will keep generating until output stops due -t / shortest etc. Our pipeline is not streaming, so we generate a default large amount trimmed later by output options in the caller.
        # The caller can set attribute _lavfi_infinite and a suggested length based on output -t etc before generation is impossible here (inputs opened before outputs parsed in our simplified flow?)
        # Main run flow can pass a hint via global variable LAVFI_SUGGESTED_SAMPLES if set.
        if nsamples is None:
            nsamples=int(globals().get('LAVFI_SUGGESTED_SAMPLES', sr*10))
        samples=[]
        # Model based on a period table: values are truncated/rounded integers in s16 range with amplitude 4095. Direct model gives the closest simple behaviour.
        # Try DDS table model (32768-entry, floor phase) which empirically matched over 90% of samples for the asset frequency.
        N=32768
        table=[int(round(4095*math.sin(2*math.pi*j/N))) for j in range(N)]
        for i in range(nsamples):
            idx=int(i*freq/sr*N)%N; samples.append(table[idx])
        return AudioData(sr,'mono',['FC'],'s16',[samples],16,[])
    if fname=='anullsrc':
        sr=int(float(kw.get('sample_rate',kw.get('r',44100))))
        layout_s=kw.get('channel_layout',kw.get('cl','stereo'))
        parsed=parse_layout(layout_s) or default_layout(2); layout,tokens=parsed
        nsamples=int(globals().get('LAVFI_SUGGESTED_SAMPLES', sr*10))
        # duration is infinite in ffmpeg; caller trims
        return AudioData(sr,layout,tokens,'s16',[[0]*nsamples for _ in tokens],16,[])
    if fname=='anoisesrc':
        sr=int(float(kw.get('sample_rate',kw.get('r',48000)))); dur_s=kw.get('duration',kw.get('d'))
        nsamples=int(round(parse_time_value(dur_s)*sr)) if dur_s else int(globals().get('LAVFI_SUGGESTED_SAMPLES',sr*10))
        # pink/white noise approximations are not bit-exact; generate white noise with a simple LCG as placeholder
        seed=int(float(kw.get('seed',kw.get('s',-1)))) if kw.get('seed',kw.get('s')) not in (None,'-1') else 12345
