        return AudioData(sr,'stereo',['FL','FR'],'s16',[vals,list(vals)],16,[])
    return None

def apply_audio_filter(audio, fname, argstr):
    args,kw=parse_filter_args(argstr)
    if fname in ('anull','aresample','anullsink'):
        # aresample may specify sample rate as first arg
        if fname=='aresample':
            sr=None
            if args:
                try: sr=int(float(args[0]))
                except Exception: pass
            if 'sample_rate' in kw: sr=int(float(kw['sample_rate']))
            if sr: return resample_audio(audio,sr)
        return audio
    if fname=='aformat':
        # aformat=sample_fmts=s16:sample_rates=44100:channel_layouts=stereo (lists separated by |)
        out=audio
        if 'sample_rates' in kw:
            try: out=resample_audio(out,int(kw['sample_rates'].split('|')[0]))
            except Exception: pass
        if 'channel_layouts' in kw:
            parsed=parse_layout(kw['channel_layouts'].split('|')[0])
            if parsed: out=remix_audio(out,parsed[0],parsed[1])
        if 'sample_fmts' in kw:
            fmt=kw['sample_fmts'].split('|')[0]
            if fmt in SAMPLE_FORMATS: out=convert_audio_format(out,fmt)
        return out
    if fname=='volume':
        vol_s=kw.get('volume', args[0] if args else '1')
        factor=None
        try:
            s=str(vol_s).strip()
            if s.lower().endswith('db'):
                factor=10**(float(s[:-2])/20)
            else:
                factor=float(s)
        except Exception:
            factor=1.0
        # apply in float domain then convert back
        is_float=SAMPLE_FORMATS[audio.sample_fmt][2]
        new_planar=[]
        for ch in audio.planar:
            col=[]
            for v in ch:
                if is_float:
                    col.append(float(v)*factor)
                else:
                    bits=SAMPLE_FORMATS[audio.sample_fmt][1]
                    if SAMPLE_FORMATS[audio.sample_fmt][3]:
                        fv=(int(v)-(1<<(bits-1)))/float(1<<(bits-1))*factor
                        y=lrint_even(fv*float(1<<(bits-1)))+(1<<(bits-1)); col.append(clamp(y,0,(1<<bits)-1))
                    else:
                        y=lrint_even(int(v)*factor); lo,hi=(-(1<<(bits-1)),(1<<(bits-1))-1); col.append(clamp(y,lo,hi))
            new_planar.append(col)
        return AudioData(audio.sample_rate,audio.layout_name,audio.tokens,audio.sample_fmt,new_planar,audio.bits_per_raw_sample,audio.metadata,audio.stream_metadata)
    if fname=='atrim':
        start=kw.get('start'); end=kw.get('end'); dur=kw.get('duration')
        sidx=0
        if start is not None:
            try: sidx=int(round(parse_time_value(start)*audio.sample_rate))
            except Exception: sidx=int(float(start))
        eidx=audio.nb_samples
        if end is not None:
            try: eidx=int(round(parse_time_value(end)*audio.sample_rate))
            except Exception: eidx=int(float(end))
        if dur is not None:
            try: eidx=sidx+int(round(parse_time_value(dur)*audio.sample_rate))
            except Exception: pass
        return audio.slice_samples(sidx,eidx)
    if fname in ('apad','apad=whole_dur'):
        return audio
    if fname=='pan':
        # pan=stereo|c0=c0|c1=c0 style is complex; not implemented accurately
        return audio
    return None
