class FfmpegStageError(Exception):
    def __init__(self, stage, filename, err_name, code):
        self.stage=stage; self.filename=filename; self.err_name=err_name; self.code=code

def err_name_from_errno(e):
    try:
        return os.strerror(e.errno) if getattr(e,'errno',None) else str(e)
    except Exception:
        return str(e)

def get_option(opts, names, default=None, spec_filter=None):
    """Return last value for any option name in names from an options list. If spec_filter is provided, it is a function(stream_spec)->bool"""
    val=default
    for o in opts:
        if o.name in names:
            if spec_filter is not None and not spec_filter(o.stream_spec):
                continue
            val=o.value
    return val

def has_option(opts, names):
    return any(o.name in names for o in opts)

def collect_options(opts, names):
    return [o for o in opts if o.name in names]

def option_bool(opts, names, default=False):
    # main boolean options have value None when present; negations are named no<name> in tokens (our split keeps spec.name as original token's base? MANUAL for negation returns OptSpec with name token_name, so check that too)
    v=default
    for o in opts:
        if o.name in names:
            v=True
        for nm in names:
            if o.name == 'no'+nm:
                v=False
    return v

def spec_matches_audio(spec, stream_index=0, audio_index=0):
    if spec is None or spec=='':
        return True
    # spec can be like 'a', 'a:0', '0', 'v', 's', 'a:1', '0:a:0' (for some options specified in a full form - not typical for output options)
    parts=str(spec).split(':')
    # Normalize: last elements that describe stream
    if parts[0] in ('a','v','s','d','t'):
        if parts[0]!='a': return False
        if len(parts)>1:
            try: return int(parts[1])==audio_index
            except Exception: return True
        return True
    if parts[0].isdigit():
        if len(parts)==1:
            return int(parts[0])==stream_index
        # form file_index:stream_type:stream_index is used for -map values not option specifiers typically
        return True
    return True

def get_stream_option(opts, names, default=None, stream_index=0, audio_index=0):
    return get_option(opts,names,default,lambda sp: spec_matches_audio(sp,stream_index,audio_index))

def parse_bool_value(v, default=True):
    if v is None: return default
    if isinstance(v,bool): return v
    s=str(v).strip().lower()
    if s in ('1','true','yes','on'): return True
    if s in ('0','false','no','off'): return False
    # AVOption bool accepts numeric expressions
    try: return float(s)!=0
    except Exception: raise ValueError(v)

def read_input_bytes(filename, input_index, in_ctx_obj):
    # Returns bytes for seekable regular inputs / stdin
    if filename=='-' or filename.startswith('pipe:'):
        return sys.stdin.buffer.read()
    path=filename
    if path.startswith('file://'):
        path=path[7:]
    elif path.startswith('file:'):
        path=path[5:]
    try:
        with open(path,'rb') as f:
            return f.read()
    except OSError as e:
        err=os.strerror(e.errno) if e.errno else str(e)
        logger.log(16, f"Error opening input: {err}\n", context=ctx(in_ctx_obj, f"in#{input_index}"))
        raise FfmpegStageError('input', filename, err, (256-(e.errno or 2))%256)

RAW_PCM_FORMATS={
    's16le':('pcm_s16le','s16',2,'<h'), 's16be':('pcm_s16be','s16',2,'>h'), 's24le':('pcm_s24le','s32',3,None), 's24be':('pcm_s24be','s32',3,None),
    's32le':('pcm_s32le','s32',4,'<i'), 's32be':('pcm_s32be','s32',4,'>i'), 's8':('pcm_s8','s16',1,'b'), 'u8':('pcm_u8','u8',1,'B'),
    'u16le':('pcm_u16le','s16',2,'<H'), 'u16be':('pcm_u16be','s16',2,'>H'), 'u24le':('pcm_u24le','s32',3,None), 'u24be':('pcm_u24be','s32',3,None),
    'u32le':('pcm_u32le','s32',4,'<I'), 'u32be':('pcm_u32be','s32',4,'>I'), 'f32le':('pcm_f32le','flt',4,'<f'), 'f32be':('pcm_f32be','flt',4,'>f'),
    'f64le':('pcm_f64le','dbl',8,'<d'), 'f64be':('pcm_f64be','dbl',8,'>d'), 'alaw':('pcm_alaw','s16',1,None), 'mulaw':('pcm_mulaw','s16',1,None),
    's64le':('pcm_s64le','s64',8,'<q'), 's64be':('pcm_s64be','s64',8,'>q'),
}

def pcm_packet_samples(sample_rate):
    if sample_rate<=0: return 4096
    target=sample_rate//10
    p=1
    while p*2<=target: p*=2
    return max(64,min(32768,p))

def guess_input_format(data, filename, forced):
    if forced:
        return forced
    if len(data)>=12 and data[:4] in (b'RIFF',b'RF64') and data[8:12]==b'WAVE':
        return 'wav'
    if data[:4]==b'fLaC':
        return 'flac'
    if data[:4]==b'OggS':
        return 'ogg'
    if data[:4]==b'FORM' and len(data)>12 and data[8:12] in (b'AIFF',b'AIFC'):
        return 'aiff'
    if data[:3]==b'ID3' or (len(data)>=2 and data[0]==0xff and (data[1]&0xe0)==0xe0):
        return 'mp3'
    ext=os.path.splitext(filename)[1].lower().lstrip('.')
    extmap={'wav':'wav','wave':'wav','flac':'flac','ogg':'ogg','oga':'ogg','aif':'aiff','aiff':'aiff','au':'au','caf':'caf'}
    return extmap.get(ext)

def open_input(group, index, global_opts):
    filename=group.filename
    in_obj=CtxObj()
    # input format option
    forced=get_option(group.options,['f'])
    # Check unknown format name against static demuxers list (must know names) - parse names from static formats/demuxers rough extraction
    if forced:
        known = _known_demuxer_names()
        # format names may be comma aliases; known set covers them
        if forced not in known and forced not in ('lavfi',):
            logger.log(16, f"Unknown input format: '{forced}'\n", context=ctx(in_obj,f"in#{index}"))
            raise FfmpegStageError('input',filename,'Invalid argument',234)
    if forced=='lavfi':
        return open_lavfi_input(group,index,in_obj)
    # For stdin with lavfi graph passed as filename without -f? Users must use -f lavfi.
    data=read_input_bytes(filename,index,in_obj)
    fmt=guess_input_format(data,filename,forced)
    if fmt is None:
        # Error messages observed for invalid data are generated in a later section - approximate
        ctxname=f"in#{index}"
        logger.log(16, f"Invalid data found when processing input\n", context=ctx(in_obj,ctxname))
        raise FfmpegStageError('input',filename,'Invalid data found when processing input',109)
    # log context name for format-specific input object used in some messages includes format
    fmt_ctx_obj=CtxObj()
    opened=None
    # Duration estimation messages for raw etc handled below
    if fmt=='wav':
        try:
            wi=wav_io.parse_wav(data)
        except Exception as e:
            logger.log(16, f"Invalid data found when processing input\n", context=ctx(in_obj,f"in#{index}"))
            raise FfmpegStageError('input',filename,'Invalid data found when processing input',109)
        audio=wi.audio
        guessed=False; tokens=wi.tokens
        if tokens is None:
            guessed=True
            _ln,tokens=default_layout(wi.channels)
            # audio object created in parse_wav already has default layout
        stream=InputStreamInfo(index=0,file_index=index,codec=wi.codec,codec_tag=wi.codec_tag,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name='wav',guessed=guessed)
        stream.input_ctx=in_obj
        # Input stream bit_rate for display is handled in codec_string.
        total_samples=wi.total_samples
        dur_us=duration_us_from_samples(total_samples,wi.sample_rate) if total_samples>0 else None
        file_size=len(data)
        if dur_us:
            bit_rate=(file_size*8*1000000)//dur_us
        else:
            bits={'pcm_u8':8,'pcm_s16le':16,'pcm_s24le':24,'pcm_s32le':32,'pcm_f32le':32,'pcm_f64le':64,'pcm_alaw':8,'pcm_mulaw':8}.get(wi.codec,16)
            bit_rate=wi.sample_rate*wi.channels*bits
        # Packets for framemd5/copy: segment raw PCM data in packet_samples
        stream.packets=make_pcm_packets(audio, wi.codec, group)
        opened=InputFileOpened(group=group,format_name='wav',metadata=wi.metadata,streams=[stream],duration_us=dur_us,file_size=file_size,bit_rate=int(bit_rate))
        opened.index=index; opened.ctx=in_obj
        # guessed layout log (warning) before dump - caller will log before dump
        return opened
    elif fmt=='flac':
        try:
            dec,frames,planar_bps=decode_flac_data(data)
        except Exception as e:
            # FLAC decoder errors are usually reported during decoding, not probing; probing may succeed if header ok
            logger.log(16, f"{e}\n", context=ctx(CtxObj(),'flac'))
            raise FfmpegStageError('input',filename,'Invalid data found when processing input',109)
        info=dec.info
        # Layout: mask tag or FLAC table
        meta=list(dec.metadata)
        mask_val=None; new_meta=[]
        for k,v in meta:
            if k.lower()=='waveformatextensible_channel_mask':
                mask_val=v
            else:
                new_meta.append((k,v))
        meta=new_meta
        if mask_val is not None:
            try:
                mask=int(str(mask_val),0); tokens=tokens_for_wave_mask(mask,info.channels); layout=layout_name_for_channels(tokens) or default_layout(info.channels)[0]
            except Exception:
                tokens=None; layout=None
        else:
            flac_layouts={1:'mono',2:'stereo',3:'3.0',4:'quad',5:'5.0',6:'5.1',7:'6.1',8:'7.1'}
            layout=flac_layouts.get(info.channels,default_layout(info.channels)[0])
            # tokens from standard layouts
            _ln,tokens=(layout, STANDARD_LAYOUTS.get(layout,default_layout(info.channels)[1]))
        sample_fmt='s16' if info.bps<=16 else 's32'
        shift=(16-info.bps) if info.bps<=16 else (32-info.bps)
        planar=[[int(x)<<shift for x in ch] for ch in planar_bps]
        audio=AudioData(info.sample_rate,layout,tokens,sample_fmt,planar,info.bps,meta)
        stream=InputStreamInfo(index=0,file_index=index,codec='flac',codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name='flac',guessed=False,extradata=info.to_bytes(),flac_info=info)
        stream.input_ctx=in_obj
        stream.packets=[{'data':raw,'duration':meta_f['blocksize'],'pts':sum(frames[j][1]['blocksize'] for j in range(i))} for i,(raw,meta_f,chans) in enumerate(frames)]
        total=info.total_samples if info.total_samples else sum(f[1]['blocksize'] for f in frames)
        dur_us=duration_us_from_samples(total,info.sample_rate) if total>0 else None
        bit_rate=(len(data)*8*1000000)//dur_us if dur_us else 0
        opened=InputFileOpened(group=group,format_name='flac',metadata=meta,streams=[stream],duration_us=dur_us,file_size=len(data),bit_rate=int(bit_rate))
        opened.index=index; opened.ctx=in_obj
        return opened
    elif fmt in RAW_PCM_FORMATS or (forced and forced in RAW_PCM_FORMATS):
        return open_raw_pcm_input(group,index,in_obj,data,fmt)
    else:
        # Unsupported input format for this reimplementation: report like a demuxer error
        logger.log(16, f"Invalid data found when processing input\n", context=ctx(in_obj,f"in#{index}"))
        raise FfmpegStageError('input',filename,'Invalid data found when processing input',109)

_known_demuxers=None
def _known_demuxer_names():
    global _known_demuxers
    if _known_demuxers is not None: return _known_demuxers
    names=set()
    try:
        txt=get_static('demuxers').decode()
        for line in txt.splitlines():
            m=re.match(r'^ [A-Za-z. ]{2} +(\S+)',line)
            if m:
                for n in m.group(1).split(','): names.add(n)
    except Exception: pass
    names.update(RAW_PCM_FORMATS.keys())
    _known_demuxers=names; return names

def make_pcm_packets(audio, codec, group=None):
    # Segment decoded audio into packets as PCM demuxer/decoder would for framecrc/framemd5 purposes.
    # Data bytes will be regenerated later from audio segments by packet data generation functions in hash paths.
    ps=pcm_packet_samples(audio.sample_rate)
    packets=[]; pos=0
    while pos<audio.nb_samples:
        dur=min(ps,audio.nb_samples-pos); packets.append({'duration':dur,'pts':pos,'start':pos,'codec':codec}); pos+=dur
    if audio.nb_samples==0:
        packets=[]
    return packets

def open_raw_pcm_input(group,index,in_obj,data,fmt):
    codec,sample_fmt,cont_bytes,fmtcode = RAW_PCM_FORMATS[fmt]
    # sample rate and layout from input options: -ar/-sample_rate, -ac/-ch_layout/-channel_layout
    sr_val=get_option(group.options,['sample_rate','ar'])
    sr=parse_rate_value(sr_val) if sr_val is not None else 44100
    # Note: -ar as an *input* option in ffmpeg for raw formats is interpreted by the demuxer? The CLI maps input -ar to codecpar sample_rate for raw.
    layout_val=get_option(group.options,['ch_layout','channel_layout'])
    ac_val=get_option(group.options,['ac'])
    if layout_val is not None:
        parsed=parse_layout(str(layout_val))
        if not parsed:
            # message observed for input ch_layout errors is in input stream context; simplify
            raise FfmpegStageError('input',group.filename,'Invalid argument',234)
        layout,tokens=parsed; channels=len(tokens)
    elif ac_val is not None:
        channels=int(parse_rate_value(ac_val)); layout,tokens=default_layout(channels)
    else:
        channels=1; layout,tokens='mono',['FC']
    frames=len(data)//(cont_bytes*channels) if channels else 0
    planar=[[] for _ in range(channels)]
    raw=data[:frames*cont_bytes*channels]
    if fmtcode:
        vals=struct.unpack(('<' if cont_bytes>1 and fmt not in ('s16be','s24be','s32be','f32be','f64be','u16be','u32be') else '')+f"{len(raw)//cont_bytes}{fmtcode[-1]}",raw) if False else None
    # simpler per format decode
    if fmt in ('s24le','s24be','u24le','u24be'):
        be=fmt.endswith('be'); signed=fmt.startswith('s')
        for i in range(frames*channels):
            chunk=raw[i*3:i*3+3]; v=int.from_bytes(chunk,'big' if be else 'little',signed=signed)
            if sample_fmt=='s32': v = v<<8 if signed else (v<<8)
            planar[i%channels].append(v)
    elif fmt in ('alaw','mulaw'):
        fn=wav_io.alaw_to_linear if fmt=='alaw' else wav_io.mulaw_to_linear
        for i,b in enumerate(raw): planar[i%channels].append(fn(b))
    else:
        # struct code char from fmtcode
        code=RAW_PCM_FORMATS[fmt][3]; prefix='>' if fmt.endswith('be') else '<'
        if fmt in ('s8','u8'): prefix=''
        vals=struct.unpack(f"{prefix}{len(raw)//cont_bytes}{code}",raw)
        # adjustments for decoders output sample formats:
        # pcm_u16 -> decoder outputs s16? value conversion: (u-32768). pcm_s8 dec outputs s16 with value<<8? Check later; for raw hash copy we use packets data separately.
        vals=list(vals)
        if fmt in ('u16le','u16be'):
            vals=[v-32768 for v in vals]
        elif fmt in ('u32le','u32be'):
            vals=[v-2147483648 for v in vals]
        elif fmt=='s8':
            vals=[v<<8 for v in vals]
        for i,v in enumerate(vals): planar[i%channels].append(v)
    bits_raw={'s16':16,'s32':32,'flt':32,'dbl':64,'u8':8,'s64':64}.get(sample_fmt,16)
    if fmt in ('s24le','s24be'): bits_raw=24
    audio=AudioData(sr,layout,tokens,sample_fmt,planar,bits_raw,[])
    logger.log(32, "Estimating duration from bitrate, this may be inaccurate\n", context=ctx(in_obj,f"in#{index}/{fmt}"))
    stream=InputStreamInfo(index=0,file_index=index,codec=codec,codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name=fmt)
    stream.input_ctx=in_obj
    stream.packets=make_pcm_packets(audio,codec,group)
    # attach raw bytes to packets for copy/hash paths
    bps_bytes=cont_bytes*channels
    for p in stream.packets:
        st=p['start']*bps_bytes; p['data']=raw[st:st+p['duration']*bps_bytes]
    dur_us=duration_us_from_samples(frames,sr) if frames>0 else None
    bits_codec={'pcm_u8':8,'pcm_s16le':16,'pcm_s16be':16,'pcm_s24le':24,'pcm_s32le':32,'pcm_f32le':32,'pcm_f64le':64}.get(codec,16)
    br=sr*channels*bits_codec
    if dur_us:
        br=(len(data)*8*1000000)//dur_us if len(data) else br
        # Observed raw dump bitrate for a small partial file was 705 kb/s for s16 (stream bitrate) when file only 8820 and duration exact gives same - for tiny 4000 bytes f32 it gave 1412 kb/s (~codec bitrate +). The stream-line bitrate is handled separate; file bitrate should approximate filesize/duration.
    opened=InputFileOpened(group=group,format_name=fmt,metadata=[],streams=[stream],duration_us=dur_us,file_size=len(data),bit_rate=int(br))
    opened.index=index; opened.ctx=in_obj
    return opened

def open_lavfi_input(group,index,in_obj):
    graph=group.filename
    # Support simple graphs with a single audio source filter and optional simple filters separated by commas
    # Tokenize by commas not inside quotes/brackets (simple)
    parts=[]; cur=''; depth=0; quote=None
    for ch in graph:
        if quote:
            cur+=ch
            if ch==quote: quote=None
        elif ch in ("'",'"'):
            quote=ch; cur+=ch
        elif ch=='[': depth+=1; cur+=ch
        elif ch==']': depth-=1; cur+=ch
        elif ch==',' and depth==0:
            parts.append(cur); cur=''
        else: cur+=ch
    if cur: parts.append(cur)
    if not parts:
        raise FfmpegStageError('input',graph,'Invalid argument',234)
    # first part should be source like sine=... or anullsrc=...; allow a leading label [out] etc ignored crudely
    audio=None; source_name=None
    for idx,part in enumerate(parts):
        p=part.strip()
        # strip link labels at start/end like [in]sine...[out]
        p=re.sub(r'^\[[^\]]+\]','',p); p=re.sub(r'\[[^\]]+\]$','',p)
        if '=' in p:
            fname,argstr=p.split('=',1)
        else:
            fname,argstr=p,''
        fname=fname.strip()
        if idx==0:
            audio=generate_lavfi_source(fname,argstr)
            source_name=fname
            if audio is None:
                logger.log(16, f"Unknown filter '{fname}'\n", context=ctx(in_obj,f"in#{index}/lavfi"))
                raise FfmpegStageError('input',graph,'Filter not found',8)
        else:
            audio=apply_audio_filter(audio,fname,argstr)
            if audio is None:
                logger.log(16, f"Unknown filter '{fname}'\n", context=ctx(in_obj,f"in#{index}/lavfi"))
                raise FfmpegStageError('input',graph,'Filter not found',8)
    # lavfi input stream codec is a PCM codec matching sample_fmt
    codecmap={'s16':'pcm_s16le','s32':'pcm_s32le','flt':'pcm_f32le','fltp':'pcm_f32le','dbl':'pcm_f64le','dblp':'pcm_f64le','u8':'pcm_u8'}
    codec=codecmap.get(audio.sample_fmt,'pcm_s16le')
    # In observed sine, stream format was s16 (the lavfi graph negotiates to s16 because sine source outputs s16)
    stream=InputStreamInfo(index=0,file_index=index,codec=codec,codec_tag=0,audio=audio,metadata=[],stream_metadata=[],duration_us=None,bit_rate=0,format_name='lavfi')
    stream.input_ctx=in_obj
    stream.packets=make_pcm_packets(audio,codec,group)
    # start 0 in dump for lavfi:
    dur_us=None
    opened=InputFileOpened(group=group,format_name='lavfi',metadata=[],streams=[stream],duration_us=dur_us,file_size=None,bit_rate=audio.sample_rate*audio.channels*16)
    opened.index=index; opened.ctx=in_obj; opened.start_time_us=0
    return opened

def parse_filter_args(argstr):
    args=[]; kwargs={}
    if not argstr: return args,kwargs
    # split by ':' not escaped / quoted (simple)
    parts=[]; cur=''; quote=None
    for ch in argstr:
        if quote:
            cur+=ch
            if ch==quote: quote=None
        elif ch in ("'",'"'):
            quote=ch; cur+=ch
        elif ch==':':
            parts.append(cur); cur=''
        else: cur+=ch
    if cur or argstr.endswith(':'): parts.append(cur)
    for p in parts:
        p=p.strip()
        if '=' in p:
            k,v=p.split('=',1); kwargs[k.strip()]=v.strip().strip("'\"")
        elif p:
            args.append(p.strip("'\""))
    return args,kwargs

def generate_lavfi_source(fname,argstr):
    args,kw=parse_filter_args(argstr)
    if fname=='sine':
        freq=float(kw.get('frequency',kw.get('f',440)))
        sr=int(float(kw.get('sample_rate',kw.get('r',44100))))
        dur_s=kw.get('duration',kw.get('d'))
        nsamples=None
        if dur_s is not None:
            try: secs=parse_time_value(dur_s)
            except Exception: secs=float(dur_s)
            nsamples=int(round(secs*sr))
        # beep_factor ignored for now (adds a beep each second if set)
        # If no duration, lavfi duration is infinite; callers may use -t output to limit. We need a finite default for standalone generation paths.
        # ffmpeg will keep generating until output stops due -t / shortest etc. Our pipeline is not streaming, so we generate a default large amount trimmed later by output options in the caller.
        # The caller can set attribute _lavfi_infinite and a suggested length based on output -t etc before generation is impossible here (inputs opened before outputs parsed in our simplified flow?)
        # Main run flow can pass a hint via global variable LAVFI_SUGGESTED_SAMPLES if set.
        if nsamples is None:
            nsamples=int(globals().get('LAVFI_SUGGESTED_SAMPLES', sr*10))
        samples=[]
        # Model based on a period table: values are truncated/rounded integers in s16 range with amplitude 4095. Direct model gives the closest simple behaviour.
        # Try DDS table model (32768-entry, floor phase) which empirically matched over 90% of samples for the asset frequency.
        N=32768
        table=[int(round(4095*math.sin(2*math.pi*j/N))) for j in range(N)]
        for i in range(nsamples):
            idx=int(i*freq/sr*N)%N; samples.append(table[idx])
        return AudioData(sr,'mono',['FC'],'s16',[samples],16,[])
    if fname=='anullsrc':
        sr=int(float(kw.get('sample_rate',kw.get('r',44100))))
        layout_s=kw.get('channel_layout',kw.get('cl','stereo'))
        parsed=parse_layout(layout_s) or default_layout(2); layout,tokens=parsed
        nsamples=int(globals().get('LAVFI_SUGGESTED_SAMPLES', sr*10))
        # duration is infinite in ffmpeg; caller trims
        return AudioData(sr,layout,tokens,'s16',[[0]*nsamples for _ in tokens],16,[])
    if fname=='anoisesrc':
        sr=int(float(kw.get('sample_rate',kw.get('r',48000)))); dur_s=kw.get('duration',kw.get('d'))
        nsamples=int(round(parse_time_value(dur_s)*sr)) if dur_s else int(globals().get('LAVFI_SUGGESTED_SAMPLES',sr*10))
        # pink/white noise approximations are not bit-exact; generate white noise with a simple LCG as placeholder
        seed=int(float(kw.get('seed',kw.get('s',-1)))) if kw.get('seed',kw.get('s')) not in (None,'-1') else 12345
        amp=float(kw.get('amplitude',kw.get('a',1.0)))
        vals=[]; x=seed & 0xffffffff
        for i in range(nsamples):
            x=(1664525*x+1013904223)&0xffffffff; vals.append(int(((x/4294967296.0)*2-1)*amp*32767))
        return AudioData(sr,'stereo',['FL','FR'],'s16',[vals,list(vals)],16,[])
    return None

def apply_audio_filter(audio, fname, argstr):
    args,kw=parse_filter_args(argstr)
    if fname in ('anull','aresample','anullsink'):
        # aresample may specify sample rate as first arg
        if fname=='aresample':
            sr=None
            if args:
                try: sr=int(float(args[0]))
                except Exception: pass
            if 'sample_rate' in kw: sr=int(float(kw['sample_rate']))
            if sr: return resample_audio(audio,sr)
        return audio
    if fname=='aformat':
