            sys.stdout.buffer.write(data); sys.stdout.buffer.flush()
        except BrokenPipeError:
            raise ExitProgram(0)
        return len(data)
    path=fn
    if path.startswith('file://'): path=path[7:]
    elif path.startswith('file:'): path=path[5:]
    with open(path,'wb') as f:
        f.write(data)
    return len(data)

def check_overwrite(plan, global_opts):
    fn=plan.group.filename
    if fn in ('-','/dev/null') or fn.startswith('pipe:'):
        return True
    path=fn[7:] if fn.startswith('file://') else fn[5:] if fn.startswith('file:') else fn
    if not os.path.exists(path):
        return True
    overwrite_yes=has_option(global_opts,['y']); overwrite_no=has_option(global_opts,['n'])
    if overwrite_yes and overwrite_no:
        # Message order in ffmpeg: it's printed during output opening after input dumps but our caller handles generic stage error.
        logger.log(16, "Error, both -y and -n supplied. Exiting.\n")
        raise FfmpegStageError('output',fn,'Invalid argument',234)
    if overwrite_yes:
        return True
    if overwrite_no:
        logger.log(32, f"File '{fn}' already exists. Exiting.\n")
        # Special termination with exit code 0 and following generic line only (handled by caller via dedicated exception below)
        raise _OverwriteRefused(fn)
    # Interaction disabled with -nostdin or stdin option false
    nostdin = has_option(global_opts,['nostdin']) or (get_option(global_opts,['stdin']) is not None and not parse_bool_value(get_option(global_opts,['stdin']),True))
    if nostdin:
        logger.log(32, f"File '{fn}' already exists. Exiting.\n")
        raise _OverwriteRefused(fn)
    # Prompt to stderr, read a char/line from stdin (text). FFmpeg reads a line and checks first char y/Y.
    try:
        sys.stderr.write(f"File '{fn}' already exists. Overwrite? [y/N] "); sys.stderr.flush()
    except Exception: pass
    try:
        line=sys.stdin.readline()
    except Exception:
        line=''
    if line and line[0] in ('y','Y'):
        return True
    logger.log(32, "Not overwriting - exiting\n")
    raise _OverwriteRefused(fn)

class _OverwriteRefused(Exception):
    def __init__(self,fn): self.filename=fn

def encode_pcm_bytes(audio, codec):
    # audio is AudioData in a sample format appropriate for codec (caller converts usual formats; alaw etc audio values are s16)
    raw=[]
    if codec=='pcm_u8':
        a=convert_audio_format(audio,'u8'); vals=[]
        for i in range(a.nb_samples):
            for c in range(a.channels): vals.append(a.planar[c][i])
        return bytes(vals)
    if codec=='pcm_s16le':
        a=convert_audio_format(audio,'s16'); out=bytearray()
        for i in range(a.nb_samples):
            for c in range(a.channels): out += struct.pack('<h',int(a.planar[c][i]))
        return bytes(out)
    if codec=='pcm_s24le':
        a=convert_audio_format(audio,'s32'); out=bytearray()
        for i in range(a.nb_samples):
            for c in range(a.channels): out += (int(a.planar[c][i])>>8).to_bytes(3,'little',signed=True) if False else ((int(a.planar[c][i])>>8)&0xffffff).to_bytes(3,'little')
        return bytes(out)
    if codec=='pcm_s32le':
        a=convert_audio_format(audio,'s32'); out=bytearray()
        for i in range(a.nb_samples):
            for c in range(a.channels): out += struct.pack('<i',int(a.planar[c][i]))
        return bytes(out)
    if codec=='pcm_f32le':
        a=convert_audio_format(audio,'flt'); out=bytearray()
        for i in range(a.nb_samples):
            for c in range(a.channels): out += struct.pack('<f',float(a.planar[c][i]))
        return bytes(out)
    if codec=='pcm_f64le':
        a=convert_audio_format(audio,'dbl'); out=bytearray()
        for i in range(a.nb_samples):
            for c in range(a.channels): out += struct.pack('<d',float(a.planar[c][i]))
        return bytes(out)
    if codec=='pcm_alaw':
        a=convert_audio_format(audio,'s16'); return bytes(wav_io.linear_to_alaw(int(a.planar[c][i])) for i in range(a.nb_samples) for c in range(a.channels))
    if codec=='pcm_mulaw':
        a=convert_audio_format(audio,'s16'); return bytes(wav_io.linear_to_mulaw(int(a.planar[c][i])) for i in range(a.nb_samples) for c in range(a.channels))
    raise ValueError(codec)

def flac_mux(packets, final_info, initial_info, metadata, seekable):
    fmt_opts_write_header=True
    out=bytearray()
    if fmt_opts_write_header:
        out += b'fLaC'
        si = (final_info if seekable else initial_info).to_bytes()
        blocks=[]
        blocks.append((0,si))
        # Vorbis comment conversion like ffmpeg: comment key -> DESCRIPTION, others as-is (keys in dict are lower-case)
        comments=[]
        for k,v in metadata:
            kk='DESCRIPTION' if k.lower()=='comment' else k
            comments.append(f"{kk}={v}".encode('utf-8'))
        if comments or True:
            vendor=LAVF_IDENT.encode(); vc=len(vendor).to_bytes(4,'little')+vendor+len(comments).to_bytes(4,'little')
            for c in comments: vc += len(c).to_bytes(4,'little')+c
            blocks.append((4,vc))
        blocks.append((1,b'\x00'*8192))
        for idx,(typ,payload) in enumerate(blocks):
            out.append(typ | (0x80 if idx==len(blocks)-1 else 0)); out += len(payload).to_bytes(3,'big'); out += payload
    for p in packets: out += p
    return bytes(out)

def stats_line(total_size, duration_us, elapsed_s, is_null=False):
    if is_null:
        size_str='N/A'
    else:
        # human readable: ffmpeg print_report uses a buffer with size in KiB/MiB etc as integer if >= 1024? Observed 9KiB for 9541; 0KiB for empty; 1KiB for 1382; larger formats need test later
        if total_size is None:
            size_str='N/A'
        elif total_size < 1024:
            size_str=f"{int(total_size)}B" if False else f"{int(total_size)//1024}KiB"
            # Observed size=0KiB / 1KiB; print_report always displays KiB for these small files? It uses `total_size/1024` style when AV_LOG? We'll use KiB units for < 1MiB, MiB with one decimal? TODO refine with probes.
            size_str=f"{int(total_size)//1024}KiB"
        elif total_size < 1024*1024:
            size_str=f"{int(total_size)//1024}KiB"
        else:
            size_str=f"{total_size/(1024*1024):.1f}MiB"
    if duration_us is None or duration_us<0:
        time_str='N/A'; bitrate_str='N/A'; speed_str='N/A'
    else:
        secs=duration_us/1e6
        time_str=format_duration_us(duration_us)
        if secs>0 and total_size:
            kbps=(total_size*8)/(secs*1000); bitrate_str=f"{kbps:6.1f}kbits/s" if kbps>=100 else f"{kbps:6.1f}kbits/s"
        else:
            bitrate_str='N/A'
        if elapsed_s>0:
            speed=secs/elapsed_s; speed_str=f"{speed:5.4g}x".rjust(5) if False else (f"{speed:4.4g}x" if speed<100 else f"{speed:.3g}x")
        else:
            speed_str='N/A'
    # elapsed format H:MM:SS.cs
    el_cs=int(elapsed_s*100); el_h=el_cs//360000; el_m=(el_cs//6000)%60; el_s=(el_cs//100)%60; el_c=el_cs%100
    elapsed_str=f"{el_h}:{el_m:02d}:{el_s:02d}.{el_c:02d}"
    if is_null:
        return f"size=N/A time={time_str} bitrate=N/A speed={speed_str} elapsed={elapsed_str}    \n"
    # Width observations: "size=       9KiB" -> value field width 10 incl unit? We'll right-justify size_str to 10
    return f"size={size_str:>10} time={time_str} bitrate={bitrate_str} speed={speed_str:>5} elapsed={elapsed_str}    \n"

def print_output_dump(plan, input_opened):
    idx=plan.index
    logger.log(32, f"Output #{idx}, {plan.fmt}, to '{plan.group.filename}':\n")
    # Format metadata printed if present (always encoder at least)
    # For some formats the display key for encoder in wav is ISFT (metadata conversion for dump is based on output format's metadata_conv: dump_format applies conversion in reverse? Observed wav output shows ISFT not encoder)
    disp_meta=[]
    for k,v in plan.metadata:
        if plan.fmt=='wav' and k.lower()=='encoder':
            disp_meta.append(('ISFT',v))
        else:
            disp_meta.append((k,v))
    # FLAC output with channel mask metadata appears in plan.metadata already (added before dump by caller if needed)
    do_print_metadata(disp_meta,2)
    # Stream line
    if plan.is_copy:
        # copy stream dump uses input codec and same layout, with tag if in wav etc. Simplify for flac->flac / wav pcm.
        instream=input_opened.streams[0]; codec_disp=codec_string_audio(instream.codec,plan.copy_tag if hasattr(plan,'copy_tag') else getattr(instream,'codec_tag',0),plan.audio,is_output=True)
    else:
        codec_obj_tag=0
        if plan.codec.startswith('pcm_'):
            # WAV tags etc; for output to non-wav raw formats dump_format may not show tag. Observed wav output shows tag for pcm_s16le; null output also omitted? Observed null output stream line: Audio: pcm_s16le, ... (no tag!) Check for null case: "Stream #0:0: Audio: pcm_s16le, 44100 Hz..." no tag. For framemd5, stream dump isn't produced in normal conversion to stdout? It is if not -v error. Default tags depend muxer.
            if plan.fmt=='wav': codec_obj_tag={'pcm_u8':1,'pcm_s16le':1,'pcm_s24le':1,'pcm_s32le':1,'pcm_f32le':3,'pcm_f64le':3,'pcm_alaw':6,'pcm_mulaw':7}.get(plan.codec,0)
            codec_disp=codec_string_audio(plan.codec,codec_obj_tag,plan.audio,is_output=True)
        elif plan.codec=='flac':
            codec_disp=codec_string_audio('flac',0xF1AC if plan.fmt=='wav' else 0,plan.audio,is_output=True)
        else:
            codec_disp=codec_string_audio(plan.codec,0,plan.audio,is_output=True)
    logger.log(32, f"  Stream #{idx}:0: Audio: {codec_disp}\n")
    # stream metadata encoder tag
    enc_name=plan.codec if not plan.is_copy else None
    smeta=list(plan.stream_metadata)
    if not plan.is_copy:
        smeta=[(k,v) for k,v in smeta if k.lower()!='encoder']; smeta.append(('encoder',f"{LAVC_IDENT} {enc_name}"))
    if smeta:
        do_print_metadata(smeta,4)

def process_one_output(plan, input_opened, global_opts, start_time):
    # plan.audio is prepared audio for encode (except copy/hash handled separately in caller)
    out_ctx_obj=plan.ctx
    # dump already printed by caller in ffmpeg order (stream mapping/press/output)
    # Encode according to format
    fmt=plan.fmt; codec=plan.codec
    data=None; packet_bytes_total=0; audio_packet_bytes=0
    if plan.is_copy:
        data, audio_packet_bytes = handle_stream_copy(plan,input_opened)
        packet_bytes_total=audio_packet_bytes
        total_written=write_output_bytes(plan,data)
        return total_written,audio_packet_bytes
    if fmt=='flac' or (codec=='flac' and fmt in ('ogg',)):
        # Build encoder options and errors at encoder opening stage (caller already did selection/dump ordering caveat).
        try:
            fopts,user_set=build_flac_options(plan.group.options)
            # sample format choice
            sfmt_opt=get_stream_option(plan.group.options,['sample_fmt'])
            if sfmt_opt is not None:
                if sfmt_opt not in ('s16','s32'):
                    raise ValueError(f"Error setting option sample_fmt to value {sfmt_opt}.")
                enc_sfmt=sfmt_opt
            else:
                src_fmt=plan.audio.sample_fmt
                if src_fmt in ('s32','s32p','s64','s64p','flt','fltp','dbl','dblp'):
                    enc_sfmt='s32'
                else:
                    enc_sfmt='s16'
            audio_enc=convert_audio_format(plan.audio,enc_sfmt)
            enc=FlacEncoder(audio_enc.sample_rate,audio_enc.channels,enc_sfmt,fopts,user_set)
            # Apply -frames:a as encoder frames truncation (approximate): truncate plane before encoding to frames*blocksize samples if set
            flim=getattr(plan.audio,'_frames_limit',None)
            # sample count after resampling (enc blocksize known now)
            if flim is not None:
                max_samp=flim*enc.blocksize
                if audio_enc.nb_samples>max_samp: audio_enc=audio_enc.slice_samples(0,max_samp)
            packets,final,initial=enc.encode(audio_enc.planar)
        except ValueError as e:
            # Encoder option error formatting
            msg=str(e)
            if msg.startswith('invalid prediction orders') or msg.startswith('invalid partition orders'):
                logger.log(16,msg+"\n",context=ctx(plan.enc_ctx,'flac'))
                logger.log(16, "Error while opening encoder - maybe incorrect parameters such as bit_rate, rate, width or height.\n", context=ctx(plan.stream_ctx,f"aost#{plan.index}:0/flac") + f" [enc:flac @ 0x{id(plan.enc_ctx):x}]")
                # Caller stage error logic for encoder opening uses Invalid argument and doesn't print Conversion failed (it might in threaded ffmpeg) - simplified to output stage error
                raise FfmpegStageError('output',plan.group.filename,'Invalid argument',234)
            elif msg.startswith('Error setting option') or msg.startswith('Unable to parse'):
                # flac context messages emulate AVOption setting errors
                if msg.startswith('Unable to parse'):
                    # Eval error line is complex; print simplified pair
                    name='compression_level'
                    logger.log(16,msg+"\n",context=ctx(plan.enc_ctx,'flac'))
                    logger.log(16, f"Error setting option {name} to value {get_stream_option(plan.group.options,[name])}.\n",context=ctx(plan.enc_ctx,'flac'))
                else:
                    logger.log(16,msg+"\n",context=ctx(plan.enc_ctx,'flac'))
                logger.log(16, "Error applying encoder options: Invalid argument\n",context=ctx(plan.stream_ctx,f"aost#{plan.index}:0/flac"))
                raise FfmpegStageError('output',plan.group.filename,'Invalid argument',234)
            raise
        write_header_opt=get_option(plan.group.options,['write_header'])
        audio_packet_bytes=sum(len(p) for p in packets)
        if write_header_opt is not None and not parse_bool_value(write_header_opt,True):
            data=b''.join(packets)
        else:
            if fmt=='ogg':
                data=ogg_mux_flac(packets,final,initial,plan.metadata,plan.seekable)
            else:
                data=flac_mux(packets,final,initial,plan.metadata,plan.seekable)
        total_written=write_output_bytes(plan,data)
        return total_written,audio_packet_bytes
    if fmt=='wav':
        if codec not in wav_io.PCM_CODEC_INFO and codec!='flac':
            raise FfmpegStageError('output',plan.group.filename,'Invalid argument',234)
        # Convert audio to sample fmt for wav codec (wav writer expects appropriate)
        sfmt_map={'pcm_u8':'u8','pcm_s16le':'s16','pcm_s24le':'s32','pcm_s32le':'s32','pcm_f32le':'flt','pcm_f64le':'dbl','pcm_alaw':'s16','pcm_mulaw':'s16'}
        audio_enc=convert_audio_format(plan.audio,sfmt_map[codec]) if codec in sfmt_map else plan.audio
        rf64_opt=get_option(plan.group.options,['rf64'])
        rf64='never'
        if rf64_opt is not None:
            # wav muxer AVOption rf64 enum: auto -1, never0, always1; string names too
            if str(rf64_opt) in ('always','1'): rf64='always'
            elif str(rf64_opt) in ('auto','-1'): rf64='auto'
        data=wav_io.write_wav_bytes(audio_enc,codec,plan.metadata,seekable=plan.seekable,rf64=rf64)
        # packet bytes = data chunk size
        audio_packet_bytes=len(encode_pcm_bytes(audio_enc,codec))
        total_written=write_output_bytes(plan,data)
        return total_written,audio_packet_bytes
    if fmt in RAW_PCM_FORMATS or fmt in ('u8','s16le','s16be','s24le','s24be','s32le','s32be','f32le','f32be','f64le','f64be','alaw','mulaw'):
        # Determine codec from format if user codec is default PCM; plan.codec was set default for format or user
        pcm_codec=codec
        # raw format names have an associated codec; if user default was pcm_s16le from WAV etc use format codec
        fmt_codec=RAW_PCM_FORMATS.get(fmt,(pcm_codec,))[0] if fmt in RAW_PCM_FORMATS else pcm_codec
        if get_stream_option(plan.group.options,['c','codec','acodec']) is None:
            pcm_codec=fmt_codec
        # Byte order variants for be are not fully implemented in encode_pcm_bytes (little assumed); handle common be by byteswap later if needed
        raw=encode_pcm_bytes_for_format(plan.audio,fmt,pcm_codec)
        total=write_output_bytes(plan,raw)
        return total,len(raw)
    if fmt=='null':
        # packets would be encoded as codec; for stats audio bytes is encoded PCM size
        enc_codec=codec or 'pcm_s16le'
        if enc_codec=='flac':
            # encode to count bytes but discard
            # Use FLAC path by recursing with a dummy plan format? Simpler count PCM size
            raw=encode_pcm_bytes(plan.audio,'pcm_s16le'); return 0,len(raw)
        raw=encode_pcm_bytes(plan.audio,enc_codec if enc_codec.startswith('pcm_') else 'pcm_s16le')
        return 0,len(raw)
    if fmt in ('md5','hash','framemd5','framehash','crc','framecrc'):
        return handle_hash_output(plan,input_opened)
    # Unsupported format fallback
    logger.log(16, f"Requested output format '{fmt}' is not known.\n", context=ctx(CtxObj(),'AVFormatContext')) if False else None
    raise FfmpegStageError('output',plan.group.filename,'Invalid argument',234)

def encode_pcm_bytes_for_format(audio, fmt, codec):
    # for be variants, generate by converting to le packs then byteswap per sample
    if fmt.endswith('be') and fmt not in ('f32be','f64be'):
        # Use little-endian equivalent codec to get bytes then swap
        le_codec={'pcm_s16be':'pcm_s16le','pcm_s24be':'pcm_s24le','pcm_s32be':'pcm_s32le'}.get(codec,codec)
        raw=encode_pcm_bytes(audio,le_codec)
        cont={'pcm_s16be':2,'pcm_s24be':3,'pcm_s32be':4}.get(codec,2)
        out=bytearray()
        for i in range(0,len(raw),cont): out += raw[i:i+cont][::-1]
        return bytes(out)
    if fmt in ('f32be','f64be'):
        a=convert_audio_format(audio,'flt' if fmt=='f32be' else 'dbl'); out=bytearray()
        code='>f' if fmt=='f32be' else '>d'
        for i in range(a.nb_samples):
            for c in range(a.channels): out += struct.pack(code,float(a.planar[c][i]))
        return bytes(out)
    return encode_pcm_bytes(audio,codec)

def ogg_mux_flac(packets, final, initial, metadata, seekable):
    # Minimal Ogg FLAC mapping: one BOS page with \x7fFLAC header packet containing fLaC + STREAMINFO, then pages with FLAC frames.
    # This is not byte-identical segmenting/CRC granule logic to ffmpeg in all cases, but produces a valid Ogg FLAC stream.
    # Build header packet
    vendor=LAVF_IDENT.encode(); comments=[]
    for k,v in metadata:
        kk='DESCRIPTION' if k.lower()=='comment' else k; comments.append(f"{kk}={v}".encode())
    vc=len(vendor).to_bytes(4,'little')+vendor+len(comments).to_bytes(4,'little')
    for c in comments: vc+=len(c).to_bytes(4,'little')+c
    # Ogg FLAC header: 0x7f 'FLAC' version 1.0, headers count 0? ffmpeg uses mapping with STREAMINFO only in first packet and comment in second? For simplicity use spec: first packet contains 0x7fFLAC + major/minor + header count (2 bytes, number of metadata blocks following excluding STREAMINFO) + 'fLaC' + metadata blocks.
    si_bytes=(final if seekable else initial).to_bytes()
    metab=b''
    # streaminfo block in header packet has last-block flag false if comment follows
    metab += bytes([0]) + len(si_bytes).to_bytes(3,'big') + si_bytes
    metab += bytes([4]) + len(vc).to_bytes(3,'big') + vc  # last flag set by last block header? comment is last if no padding
    # set last flag on comment block start (position of block header first byte) - adjust: streaminfo is 38 bytes into metab
    mb=bytearray(metab); mb[38] |= 0x80; metab=bytes(mb)
    first_packet=b'\x7fFLAC' + bytes([1,0]) + (1).to_bytes(2,'big') + b'fLaC' + metab
    pages=[]; serial=0x12345678
    seq=0
    def ogg_page(packets_list, granule, bos=False,eos=False,continued=False):
        nonlocal seq
        segs=[]; data=b''
        for p in packets_list:
            data+=p
            remaining=len(p)
            while remaining>=255:
                segs.append(255); remaining-=255
            segs.append(remaining)
        header_type=(2 if bos else 0)|(4 if eos else 0)|(1 if continued else 0)
        header=b'OggS'+bytes([0,header_type])+struct.pack('<q',granule)+struct.pack('<I',serial)+struct.pack('<I',seq)+b'\x00\x00\x00\x00'+bytes([len(segs)])+bytes(segs)
        page=bytearray(header+data)
        # CRC32 Ogg polynomial 0x04c11db7 non-reflected - compute with custom table
        crc=ogg_crc(page); page[22:26]=struct.pack('<I',crc); seq+=1; return bytes(page)
    pages.append(ogg_page([first_packet],0,bos=True))
    gran=0
    # Frames granule = cumulative samples; need blocksize per frame from packets parse quickly via decoder on wrapped data is heavy. Caller sizes are not available; approximate using final total / packets not known.
    # This lightweight mux is a fallback; granule set to final total on last frame and intermediate proportionally by file position is unacceptable for tools, but ffmpeg can decode Ogg packets regardless granule for timing roughly.
    for idx,p in enumerate(packets):
        gran = final.total_samples if idx==len(packets)-1 else 0
        pages.append(ogg_page([p],gran,eos=(idx==len(packets)-1)))
    return b''.join(pages)

_ogg_crc_table=None
def ogg_crc(data):
    global _ogg_crc_table
    if _ogg_crc_table is None:
        poly=0x04c11db7; tab=[]
        for i in range(256):
            r=i<<24
            for _ in range(8): r=((r<<1) ^ poly) & 0xffffffff if (r & 0x80000000) else (r<<1)&0xffffffff
            tab.append(r)
        _ogg_crc_table=tab
    crc=0
    for b in data: crc=((crc<<8)&0xffffffff) ^ _ogg_crc_table[((crc>>24)^b)&0xff]
    return crc

def handle_stream_copy(plan,input_opened):
    # Limited: flac->flac and wav/pcm->wav/raw/hash formats are handled in their dedicated paths.
    # This function is called only from process_one_output when is_copy, but our main flow routes hash formats separately.
    instream=input_opened.streams[0]
    if plan.fmt=='flac' and instream.codec=='flac':
        # Use original frame packets (respect input trims already at packet level is NOT done here; our main flow for copy will trim by audio and this is a simplification)
        packets=[p['data'] for p in instream.packets if 'data' in p]
        # If packets weren't attached raw for flac input (they are from flac parser)
        data=flac_mux(packets, instream.flac_info, instream.flac_info, plan.metadata, plan.seekable)
        return data,sum(len(p) for p in packets)
    if plan.fmt=='wav' and instream.codec=='flac':
        # FLAC in WAV
        packets=[p['data'] for p in instream.packets if 'data' in p]
        data=wav_write_flac_copy(plan,instream,packets)
        return data,sum(len(p) for p in packets)
    # Fallback: behave like a PCM re-encode if codecs compatible
    if plan.fmt=='wav':
        data=wav_io.write_wav_bytes(plan.audio, instream.codec if instream.codec in wav_io.PCM_CODEC_INFO else 'pcm_s16le', plan.metadata, seekable=plan.seekable)
        return data, sum(len(p.get('data',b'')) for p in instream.packets)
    raise FfmpegStageError('output',plan.group.filename,'Invalid argument',234)

def wav_write_flac_copy(plan,instream,packets):
    # Build WAV with FLAC codec tag, fmt includes STREAMINFO extradata
    audio=plan.audio; sr=audio.sample_rate; ch=audio.channels; bits=16 if instream.flac_info.bps<=16 else instream.flac_info.bps
    extra=instream.flac_info.to_bytes(); fmt_body=struct.pack('<HHIIHH',0xf1ac,ch,sr,0,2,16)+struct.pack('<H',len(extra))+extra
    fmt_chunk=b'fmt '+struct.pack('<I',len(fmt_body))+fmt_body
    fact=b'fact'+struct.pack('<I',4)+struct.pack('<I',audio.nb_samples)
    # Metadata LIST with ISFT only (plan.metadata)
    meta_map={k.lower():v for k,v in plan.metadata}
    info_data=bytearray(b'INFO')
