def hash_algo_by_name(name):
    import hashlib
    nm=name.upper()
    if nm=='MD5': return hashlib.md5()
    if nm=='SHA256': return hashlib.sha256()
    if nm=='SHA224': return hashlib.sha224()
    if nm=='SHA384': return hashlib.sha384()
    if nm=='SHA512': return hashlib.sha512()
    if nm=='SHA1': return hashlib.sha1()
    raise ValueError(name)
def adler32(data, value=1):
    # implement av_adler32_update
    A=value & 0xffff; B=(value>>16)&0xffff
    for b in data:
        A=(A+b)%65521; B=(B+A)%65521
    return (B<<16)|A

def packet_bytes_for_segment(audio, codec, start, dur):
    seg=audio.slice_samples(start,start+dur)
    if codec=='flac':
        return None
    # For hash of decoded output, default codec is pcm_s16le in hash muxers, converted by caller
    return encode_pcm_bytes(seg, codec if codec.startswith('pcm_') else 'pcm_s16le')

