vals=struct.unpack('<33075h',open('/tmp/sine_table.raw','rb').read()[:33075*2]); s=vals[:32768]
def evaluate(gen):
    pred=list(gen); errs=[a-b for a,b in zip(s,pred)]; return sum(e==0 for e in errs),sum(abs(e) for e in errs),collections.Counter(errs)
def gen(mode,amp=4095):
    step=2*math.pi/32768; x=0.0; y=1.0  # x=sin, y=cos
    for i in range(32768):
        yield round(x*amp)
        if mode=='explicit':
            x,y=x+step*y, y-step*x
        elif mode=='symplectic_sfirst':
            x=x+step*y; y=y-step*x
        elif mode=='symplectic_cfirst':
            y=y-step*x; x=x+step*y
        elif mode=='rot_double':
            c=math.cos(step); sn=math.sin(step); x,y=x*c+y*sn, y*c-x*sn
        elif mode=='midpoint':
            # midpoint method for harmonic oscillator maybe
            xm=x+0.5*step*y; ym=y-0.5*step*x; x,y=x+step*ym,y-step*xm
for mode in ['explicit','symplectic_sfirst','symplectic_cfirst','rot_double','midpoint']:
    print(mode,evaluate(gen(mode)))
