import sys,subprocess,random,math
sys.path.insert(0,'/tmp'); from genwav import write_wav; from flacparse import parse
sys.path.insert(0,'/workspace/src'); from flac_codec import FlacEncoder,FlacOptions

def gen(trial):
    rnd=random.Random(trial); mode=trial%4; ch=1 if trial%3 else 2; sr=rnd.choice([8000,22050,44100,48000]); n=rnd.choice([100,1000,4410,10000]); sam=[]; ys=[0.0]*ch
    for i in range(n):
        vals=[]
        for c in range(ch):
            if mode==0: v=rnd.randint(-20000,20000)
            elif mode==1: ys[c]=0.85*ys[c]+rnd.uniform(-8000,8000); v=int(ys[c])
            elif mode==2: v=int(10000*math.sin(2*math.pi*(300+c*100)*i/sr)+rnd.randint(-2000,2000))
            else: v=int(12000*math.sin(2*math.pi*1000*i/sr))
            vals.append(max(-32767,min(32767,v)))
        sam.append(tuple(vals))
    write_wav('/tmp/t.wav',sr,ch,16,sam); return sam,sr,ch,n,mode

def fixed_resid_abs(seq,order):
    s=0
    for i in range(order,len(seq)):
        if order==0: r=seq[i]
        elif order==1: r=seq[i]-seq[i-1]
        elif order==2: r=seq[i]-2*seq[i-1]+seq[i-2]
        s+=abs(r)
    return s

def block_metrics(sam):
    L=[x[0] for x in sam]; R=[x[1] for x in sam]; S=[l-r for l,r in zip(L,R)]; M=[(l+r)>>1 for l,r in zip(L,R)]
    seqs={'L':L,'R':R,'S':S,'M':M}; metrics={}
    for name,fn in [('rawabs',lambda q:sum(abs(x) for x in q)),('sq',lambda q:sum(x*x for x in q)),('f1',lambda q:fixed_resid_abs(q,1)),('f2',lambda q:fixed_resid_abs(q,2)),('bestfixed',lambda q:min(fixed_resid_abs(q,o) for o in range(5)))]:
        vals={k:fn(q) for k,q in seqs.items()}; costs={1:vals['L']+vals['R'],8:vals['L']+vals['S'],9:vals['R']+vals['S'],10:vals['M']+vals['S']}; metrics[name]=min(costs,key=lambda k:costs[k])
    # LPC bits estimate using our encoder subframe estimate on wasted-removed sequences as process does:
    enc=FlacEncoder(44100,2,'s16',FlacOptions())
    costs={}
    cache={}
    for k,q in seqs.items():
