        seq2=[x>>wasted for x in q]; bps=(17 if k=='S' else 16)-wasted
        cache[k]=enc._subframe_bits_estimate(seq2,bps)
    pair={1:cache['L']+cache['R'],8:cache['L']+cache['S'],9:cache['R']+cache['S'],10:cache['M']+cache['S']}; metrics['lpcbits']=min(pair,key=lambda k:pair[k])
    return metrics
for trial in [0,6,9,12,18,21,24]:
    sam,sr,ch,n,mode=gen(trial); subprocess.run(['/tmp/original_ffmpeg','-v','error','-y','-i','/tmp/t.wav','/tmp/t.flac'],check=True); info,_,f,_=parse('/tmp/t.flac'); actual=f[0]['chassign']; print('trial',trial,'mode',mode,'actual chassign',actual,'pred metrics',block_metrics(sam[:f[0]['bs']]))
